import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import type { Quote } from '../types';

const FALLBACK_IMAGES = [
  "https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?q=80&w=1080&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1502082553048-f009c37129b9?q=80&w=1080&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1497436072909-60f360e1d4b1?q=80&w=1080&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?q=80&w=1080&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1518531933037-91b2f5f229cc?q=80&w=1080&auto=format&fit=crop"
];

const getRandomFallbackImage = () => FALLBACK_IMAGES[Math.floor(Math.random() * FALLBACK_IMAGES.length)];
const generateId = () => Date.now().toString(36) + Math.random().toString(36).substring(2);

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function withRetry<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const errorMsg = error?.message?.toLowerCase() || "";
    const isRetryable = errorMsg.includes('overloaded') || errorMsg.includes('503') || errorMsg.includes('unavailable') || errorMsg.includes('429');

    if (isRetryable && retries > 0) {
      await sleep(delay);
      return withRetry(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

const cleanJsonString = (str: string | undefined): string => {
  if (!str) return "{}";
  let cleaned = str.trim();
  // Remove markdown code blocks
  cleaned = cleaned.replace(/^```json\s*/, "").replace(/```$/, "").trim();
  return cleaned;
};

export async function getPhilosophicalQuotes(theme: string): Promise<Quote[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await withRetry(() => ai.models.generateContent({
    model: "gemini-3-flash-preview", 
    contents: `Gere um array JSON com 3 citações curtas e profundas em Português sobre o tema '${theme}'. Use filósofos reais e renomados.`,
    config: {
      responseMimeType: "application/json",
      thinkingConfig: { thinkingBudget: 0 },
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            quote: { type: Type.STRING },
            author: { type: Type.STRING },
          },
          required: ["quote", "author"],
        }
      },
    },
  }));

  try {
    const jsonString = cleanJsonString(response.text);
    const quotesRaw = JSON.parse(jsonString);
    return quotesRaw.map((q: any) => ({ ...q, id: generateId(), imageUrl: '' }));
  } catch (e) {
    console.error("Erro no parse de citações:", e);
    return [];
  }
}

export async function getQuoteOfTheDay(): Promise<Quote> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await withRetry(() => ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Gere 1 citação filosófica inspiradora em Português sobre sabedoria e vida. Retorne em formato JSON.`,
    config: {
      responseMimeType: "application/json",
      thinkingConfig: { thinkingBudget: 0 },
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          quote: { type: Type.STRING },
          author: { type: Type.STRING },
        },
        required: ["quote", "author"],
      },
    },
  }));

  const jsonString = cleanJsonString(response.text);
  const dailyQuoteRaw = JSON.parse(jsonString);
  const imageUrl = await generateQuoteImage(dailyQuoteRaw.quote);
  return { ...dailyQuoteRaw, id: generateId(), imageUrl };
}

export async function generateQuoteImage(quoteText: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // 1. Analisar o prompt visual ideal
    const analysisResponse = await withRetry(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Descreva uma imagem cinematográfica e minimalista que ilustre o sentimento desta frase: "${quoteText}". 
      Instruções: Foco em paisagem, cosmos ou arquitetura. SEM PESSOAS, SEM ROSTOS, SEM TEXTO. Iluminação suave e cores elegantes. Responda apenas com o prompt em inglês.`,
      config: { thinkingConfig: { thinkingBudget: 0 } }
    }));

    const visualPrompt = analysisResponse.text || "Cinematic landscape, minimalist, ethereal lighting, high resolution, 8k, nature photography";

    // 2. Gerar imagem com Gemini 2.5 Flash Image
    const imageResponse = await withRetry(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `${visualPrompt}, cinematic composition, no people, no text, artistic, moody lighting, 9:16 aspect ratio` }] },
      config: {
        imageConfig: { aspectRatio: "9:16" }
      },
    }));

    let base64Image: string | null = null;
    if (imageResponse.candidates?.[0]?.content?.parts) {
      for (const part of imageResponse.candidates[0].content.parts) {
        if (part.inlineData?.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (base64Image) {
      return `data:image/jpeg;base64,${base64Image}`;
    }
    throw new Error("Falha na geração da imagem");

  } catch (error) {
    console.warn("Recorrendo a imagem de fallback...");
    return getRandomFallbackImage();
  }
}

import React, { useState, useCallback, useEffect } from 'react';
import { SearchBar } from './components/SearchBar';
import { QuoteCard } from './components/QuoteCard';
import { Spinner } from './components/Spinner';
import { getPhilosophicalQuotes, getQuoteOfTheDay, generateQuoteImage } from './services/geminiService';
import type { Quote } from './types';
import { SophiaIcon, SearchIcon, BookmarkIcon, RefreshIcon } from './components/Icons';

type ViewState = 'search' | 'favorites';

const App: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [dailyQuote, setDailyQuote] = useState<Quote | null>(null);
  const [isDailyQuoteLoading, setIsDailyQuoteLoading] = useState<boolean>(true);

  const [favorites, setFavorites] = useState<Quote[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('search');

  useEffect(() => {
    const savedFavorites = localStorage.getItem('sophia_favorites');
    if (savedFavorites) {
      try {
        setFavorites(JSON.parse(savedFavorites));
      } catch (e) {
        console.error("Erro ao carregar favoritos", e);
      }
    }
    fetchDailyQuote();
  }, []);

  useEffect(() => {
    localStorage.setItem('sophia_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const handleApiError = (err: any) => {
    console.error("Erro na App:", err);
    const msg = err.message || "";
    if (msg.includes("429")) return "Muitas solicitações. Aguarde um momento.";
    if (msg.includes("503") || msg.includes("overloaded")) return "O serviço está instável agora. Tente novamente.";
    return "Ocorreu um erro ao buscar sabedoria. Verifique sua conexão.";
  };

  const fetchDailyQuote = async () => {
    setIsDailyQuoteLoading(true);
    setError(null);
    try {
      const quote = await getQuoteOfTheDay();
      setDailyQuote(quote);
    } catch (err: any) {
      console.error(err);
      // Não bloqueia a interface se a citação diária falhar, apenas limpa
      setDailyQuote(null);
    } finally {
      setIsDailyQuoteLoading(false);
    }
  };

  const handleSearch = useCallback(async () => {
    if (!searchTerm.trim()) return;
    setIsLoading(true);
    setError(null);
    setQuotes([]);
    setCurrentView('search');

    try {
      const fetchedQuotes = await getPhilosophicalQuotes(searchTerm);
      if (fetchedQuotes.length === 0) {
        setError('Não encontramos pensamentos sobre este tema hoje.');
        setIsLoading(false);
        return;
      }

      const quotesWithImagesPromises = fetchedQuotes.map(async (quote) => {
        const imageUrl = await generateQuoteImage(quote.quote);
        return { ...quote, imageUrl };
      });

      const resolvedQuotes = await Promise.all(quotesWithImagesPromises);
      setQuotes(resolvedQuotes);
    } catch (err: any) {
      setError(handleApiError(err));
    } finally {
      setIsLoading(false);
    }
  }, [searchTerm]);

  const handleRegenerateImage = async (quote: Quote) => {
    try {
      const newImageUrl = await generateQuoteImage(quote.quote);
      setQuotes(prev => prev.map(q => q.id === quote.id ? { ...q, imageUrl: newImageUrl } : q));
      if (dailyQuote?.id === quote.id) setDailyQuote(prev => prev ? { ...prev, imageUrl: newImageUrl } : null);
      setFavorites(prev => prev.map(q => q.quote === quote.quote ? { ...q, imageUrl: newImageUrl } : q));
    } catch (err) {
      console.error("Erro ao trocar imagem:", err);
    }
  };

  const toggleFavorite = (quote: Quote) => {
    setFavorites(prev => {
      const exists = prev.some(fav => fav.quote === quote.quote);
      return exists ? prev.filter(fav => fav.quote !== quote.quote) : [quote, ...prev];
    });
  };

  return (
    <div className="bg-[#050505] min-h-screen text-white flex justify-center items-center p-0 sm:p-4">
      <div className="w-full max-w-md h-screen sm:h-[90vh] bg-gray-900 sm:rounded-[40px] shadow-2xl flex flex-col overflow-hidden border-x border-gray-800 relative">
        <header className="pt-8 pb-4 px-6 text-center flex flex-col items-center bg-gray-900 z-30">
          <div className="flex justify-center items-center gap-2 mb-4">
            <SophiaIcon className="w-7 h-7 text-blue-400" />
            <h1 className="text-2xl font-serif-display font-bold tracking-[0.1em] text-gray-100">SOPHIA</h1>
          </div>

          <div className="flex bg-gray-800/50 backdrop-blur-md p-1 rounded-full w-full max-w-[280px] border border-white/5">
             <button 
                onClick={() => setCurrentView('search')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 px-4 rounded-full text-[10px] uppercase tracking-widest font-bold transition-all ${currentView === 'search' ? 'bg-blue-600 text-white' : 'text-gray-500'}`}
             >
                <SearchIcon className="w-3 h-3" /> Explorar
             </button>
             <button 
                onClick={() => setCurrentView('favorites')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 px-4 rounded-full text-[10px] uppercase tracking-widest font-bold transition-all ${currentView === 'favorites' ? 'bg-blue-600 text-white' : 'text-gray-500'}`}
             >
                <BookmarkIcon className="w-3 h-3" fill={currentView === 'favorites'} /> Favoritos
             </button>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-hide">
          {currentView === 'favorites' ? (
            <div className="animate-fadeIn space-y-6">
                {favorites.length === 0 ? (
                    <div className="flex flex-col justify-center items-center h-64 text-center text-gray-600">
                        <BookmarkIcon className="w-12 h-12 opacity-10 mb-4" />
                        <p className="text-sm">Sua biblioteca está vazia.</p>
                    </div>
                ) : (
                    <>
                        <h2 className="text-center font-serif-display text-lg text-blue-300 opacity-60">Biblioteca Pessoal</h2>
                        {favorites.map((fav) => (
                            <QuoteCard key={fav.id} quote={fav} isFavorite={true} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </>
                )}
            </div>
          ) : (
            <div className="animate-fadeIn space-y-6">
                <div className="sticky top-0 z-20 bg-gray-900/80 backdrop-blur-xl pb-2">
                    <SearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} onSearch={handleSearch} isLoading={isLoading} />
                </div>

                {isLoading ? (
                    <div className="flex flex-col justify-center items-center py-20">
                      <Spinner />
                      <p className="mt-6 text-gray-500 text-xs uppercase tracking-widest animate-pulse">Materializando Pensamentos</p>
                    </div>
                ) : quotes.length > 0 ? (
                    quotes.map((quote, index) => (
                        <QuoteCard key={quote.id || index} quote={quote} isFavorite={favorites.some(f => f.quote === quote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                    ))
                ) : error ? (
                    <div className="flex flex-col justify-center items-center py-16 text-center px-8">
                        <div className="bg-red-500/10 p-4 rounded-full mb-4">
                            <SophiaIcon className="w-10 h-10 text-red-400 opacity-50" />
                        </div>
                        <p className="text-red-300/80 text-sm font-medium mb-6">{error}</p>
                        <button onClick={() => window.location.reload()} className="flex items-center gap-2 px-6 py-2 bg-gray-800 rounded-full text-xs font-bold text-white">
                            <RefreshIcon className="w-3 h-3" /> Tentar Novamente
                        </button>
                    </div>
                ) : (
                    <div className="space-y-10">
                        {isDailyQuoteLoading ? (
                            <div className="flex flex-col justify-center items-center py-10">
                                <Spinner />
                                <p className="mt-4 text-[10px] text-gray-600 uppercase tracking-widest">Sincronizando com o Infinito</p>
                            </div>
                        ) : dailyQuote && (
                            <div className="animate-slideUp">
                                <h2 className="text-center font-serif-display text-lg text-gray-500 mb-6 italic">Inspiração do Dia</h2>
                                <QuoteCard quote={dailyQuote} isFavorite={favorites.some(f => f.quote === dailyQuote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                            </div>
                        )}
                        {!isDailyQuoteLoading && !dailyQuote && !searchTerm && (
                          <div className="text-center py-20 px-10">
                            <SophiaIcon className="w-16 h-16 mx-auto opacity-10 mb-6" />
                            <p className="text-gray-500 text-sm italic">"A vida não examinada não vale a pena ser vivida."</p>
                            <p className="text-gray-700 text-[10px] mt-2 uppercase tracking-widest">— Sócrates</p>
                          </div>
                        )}
                    </div>
                )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      allowTaint: false,
      scale: 2,
      backgroundColor: '#000000',
      logging: false,
      ignoreElements: (element) => element.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const image = canvas.toDataURL("image/jpeg", 0.9);
      const link = document.createElement('a');
      link.download = `sophia-thought-${Date.now()}.jpg`;
      link.href = image;
      link.click();
    } catch (error) {
      console.error(error);
    } finally {
      setIsDownloading(false);
    }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsSharing(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-quote.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'Sophia: Pensamentos',
        });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Citação copiada para a área de transferência.');
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsSharing(false);
    }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    try {
      await onRegenerateImage(quote);
    } finally {
      setIsRegenerating(false);
    }
  };

  return (
    <div className="space-y-4 animate-fadeIn">
      <div ref={cardRef} className="relative w-full aspect-[9/16] rounded-3xl overflow-hidden shadow-2xl bg-black border border-white/5 group">

        {quote.imageUrl ? (
            <img 
                src={quote.imageUrl} 
                alt="Background" 
                onLoad={() => setIsImageLoaded(true)}
                className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-1000 ${isImageLoaded ? 'opacity-70' : 'opacity-0'}`}
            />
        ) : (
          <div className="absolute inset-0 bg-gradient-to-br from-gray-900 to-black opacity-50"></div>
        )}

        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/30 to-black/10 z-0"></div>

        <div className="absolute inset-0 flex flex-col justify-between p-10 text-white z-10">
            <div className="pt-20">
                <span className="block w-12 h-0.5 bg-blue-500/50 mb-6 rounded-full"></span>
                <blockquote className="font-serif-display text-2xl sm:text-3xl font-medium leading-relaxed tracking-wide italic text-gray-100">
                    “{quote.quote}”
                </blockquote>
            </div>

            <div className="pb-10">
                <cite className="font-serif-display text-xl text-blue-100 not-italic block">
                    — {quote.author}
                </cite>
            </div>
        </div>

        {/* Elementos excluídos da captura */}
        <div className="exclude-from-capture absolute top-6 right-6 flex gap-3 z-30">
            <button
                onClick={onImageChange}
                disabled={isRegenerating}
                className="p-3 rounded-full bg-black/20 hover:bg-black/40 backdrop-blur-xl border border-white/10 transition-all active:scale-90"
            >
                <RefreshIcon className={`w-5 h-5 text-white/80 ${isRegenerating ? 'animate-spin text-blue-400' : ''}`} />
            </button>
            <button
                onClick={() => onToggleFavorite?.(quote)}
                className="p-3 rounded-full bg-black/20 hover:bg-black/40 backdrop-blur-xl border border-white/10 transition-all active:scale-90"
            >
                <HeartIcon className={`w-5 h-5 ${isFavorite ? 'text-red-500' : 'text-white/80'}`} fill={isFavorite} />
            </button>
        </div>

        <div className="absolute bottom-6 left-0 right-0 text-center opacity-30 text-[8px] uppercase tracking-[0.3em] font-bold text-white z-10 pointer-events-none">
            Sophia • Biblioteca de Pensamentos
        </div>

        {(isRegenerating || !isImageLoaded) && (
            <div className="absolute inset-0 bg-gray-900/90 flex flex-col items-center justify-center z-40 backdrop-blur-sm">
                <Spinner />
                <span className="text-[10px] text-gray-500 mt-4 uppercase tracking-[0.2em] font-bold">Cultivando Estética</span>
            </div>
        )}
      </div>

      <div className="flex gap-2 px-1">
            <button
                onClick={handleShare}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-white text-black font-bold py-4 rounded-2xl flex items-center justify-center gap-2 transition-all active:scale-95 text-xs uppercase tracking-widest"
            >
                <ShareIcon className="w-4 h-4" /> Enviar
            </button>
            <button
                onClick={handleDownload}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-gray-800 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 transition-all active:scale-95 text-xs uppercase tracking-widest border border-white/5"
            >
                <DownloadIcon className="w-4 h-4" /> Salvar
            </button>
      </div>
    </div>
  );
};

