export async function generateQuoteImage(quoteText: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // 1. Analisar o prompt visual ideal
    // Explicitly typing analysisResponse as GenerateContentResponse to fix line 110 error
    const analysisResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Descreva uma imagem cinematográfica e minimalista que ilustre o sentimento desta frase: "${quoteText}". 
      Instruções: Foco em paisagem, cosmos ou arquitetura. SEM PESSOAS, SEM ROSTOS, SEM TEXTO. Iluminação suave e cores elegantes. Responda apenas com o prompt em inglês.`,
      config: { thinkingConfig: { thinkingBudget: 0 } }
    }));

    const visualPrompt = analysisResponse.text || "Cinematic landscape, minimalist, ethereal lighting, high resolution, 8k, nature photography";

    // 2. Gerar imagem com Gemini 2.5 Flash Image
    // Explicitly typing imageResponse as GenerateContentResponse to fix lines 122, 123 errors
    const imageResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `${visualPrompt}, cinematic composition, no people, no text, artistic, moody lighting, 9:16 aspect ratio` }] },
      config: {
        imageConfig: { aspectRatio: "9:16" }
      },
    }));

    let base64Image: string | null = null;
    if (imageResponse.candidates?.[0]?.content?.parts) {
      for (const part of imageResponse.candidates[0].content.parts) {
        if (part.inlineData?.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (base64Image) {
      return `data:image/jpeg;base64,${base64Image}`;
    }
    throw new Error("Falha na geração da imagem");

  } catch (error) {
    console.warn("Recorrendo a imagem de fallback...");
    return getRandomFallbackImage();
  }
}

import React, { useRef, useState, useEffect } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import { Spinner } from './Spinner';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      allowTaint: false,
      scale: 2,
      backgroundColor: '#000000',
      logging: false,
      ignoreElements: (element) => element.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const image = canvas.toDataURL("image/jpeg", 0.9);
      const link = document.createElement('a');
      link.download = `sophia-thought-${Date.now()}.jpg`;
      link.href = image;
      link.click();
    } catch (error) {
      console.error(error);
    } finally {
      setIsDownloading(false);
    }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsSharing(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-quote.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'Sophia: Pensamentos',
        });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Citação copiada para a área de transferência.');
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsSharing(false);
    }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    try {
      await onRegenerateImage(quote);
    } finally {
      setIsRegenerating(false);
    }
  };

  return (
    <div className="space-y-4 animate-fadeIn">
      <div ref={cardRef} className="relative w-full aspect-[9/16] rounded-3xl overflow-hidden shadow-2xl bg-black border border-white/5 group">

        {quote.imageUrl ? (
            <img 
                src={quote.imageUrl} 
                alt="Background" 
                onLoad={() => setIsImageLoaded(true)}
                className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-1000 ${isImageLoaded ? 'opacity-70' : 'opacity-0'}`}
            />
        ) : (
          <div className="absolute inset-0 bg-gradient-to-br from-gray-900 to-black opacity-50"></div>
        )}

        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/30 to-black/10 z-0"></div>

        <div className="absolute inset-0 flex flex-col justify-between p-10 text-white z-10">
            <div className="pt-20">
                <span className="block w-12 h-0.5 bg-blue-500/50 mb-6 rounded-full"></span>
                <blockquote className="font-serif-display text-2xl sm:text-3xl font-medium leading-relaxed tracking-wide italic text-gray-100">
                    “{quote.quote}”
                </blockquote>
            </div>

            <div className="pb-10">
                <cite className="font-serif-display text-xl text-blue-100 not-italic block">
                    — {quote.author}
                </cite>
            </div>
        </div>

        {/* Elementos excluídos da captura */}
        <div className="exclude-from-capture absolute top-6 right-6 flex gap-3 z-30">
            <button
                onClick={onImageChange}
                disabled={isRegenerating}
                className="p-3 rounded-full bg-black/20 hover:bg-black/40 backdrop-blur-xl border border-white/10 transition-all active:scale-90"
            >
                <RefreshIcon className={`w-5 h-5 text-white/80 ${isRegenerating ? 'animate-spin text-blue-400' : ''}`} />
            </button>
            <button
                onClick={() => onToggleFavorite?.(quote)}
                className="p-3 rounded-full bg-black/20 hover:bg-black/40 backdrop-blur-xl border border-white/10 transition-all active:scale-90"
            >
                <HeartIcon className={`w-5 h-5 ${isFavorite ? 'text-red-500' : 'text-white/80'}`} fill={isFavorite} />
            </button>
        </div>

        <div className="absolute bottom-6 left-0 right-0 text-center opacity-30 text-[8px] uppercase tracking-[0.3em] font-bold text-white z-10 pointer-events-none">
            Sophia • Biblioteca de Pensamentos
        </div>

        {(isRegenerating || !isImageLoaded) && (
            <div className="absolute inset-0 bg-gray-900/90 flex flex-col items-center justify-center z-40 backdrop-blur-sm">
                <Spinner />
                <span className="text-[10px] text-gray-500 mt-4 uppercase tracking-[0.2em] font-bold">Cultivando Estética</span>
            </div>
        )}
      </div>

      <div className="flex gap-2 px-1">
            <button
                onClick={handleShare}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-white text-black font-bold py-4 rounded-2xl flex items-center justify-center gap-2 transition-all active:scale-95 text-xs uppercase tracking-widest"
            >
                <ShareIcon className="w-4 h-4" /> Enviar
            </button>
            <button
                onClick={handleDownload}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-gray-800 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 transition-all active:scale-95 text-xs uppercase tracking-widest border border-white/5"
            >
                <DownloadIcon className="w-4 h-4" /> Salvar
            </button>
      </div>
    </div>
  );
};

