import React, { useState, useCallback, useEffect } from 'react';
import { SearchBar } from './components/SearchBar';
import { QuoteCard } from './components/QuoteCard';
import { Spinner } from './components/Spinner';
import { getPhilosophicalQuotes, getRandomQuote, generateQuoteImage } from './services/geminiService';
import type { Quote } from './types';
import { SophiaIcon, SearchIcon, BookmarkIcon, RefreshIcon } from './components/Icons';

type ViewState = 'search' | 'favorites';

const App: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [randomQuote, setRandomQuote] = useState<Quote | null>(null);
  const [isRandomLoading, setIsRandomLoading] = useState<boolean>(true);

  const [favorites, setFavorites] = useState<Quote[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('search');

  useEffect(() => {
    const savedFavorites = localStorage.getItem('sophia_favorites');
    if (savedFavorites) {
      try {
        setFavorites(JSON.parse(savedFavorites));
      } catch (e) {
        console.error("Erro ao carregar favoritos", e);
      }
    }
    fetchRandomQuote();
  }, []);

  useEffect(() => {
    localStorage.setItem('sophia_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const handleApiError = (err: any) => {
    console.error("Erro na App:", err);
    const msg = err.message || "";
    if (msg.includes("429")) return "Muitas solicitações. Aguarde.";
    if (msg.includes("503") || msg.includes("overloaded")) return "Serviço instável. Tente novamente.";
    return "Erro ao buscar sabedoria.";
  };

  const fetchRandomQuote = async () => {
    setIsRandomLoading(true);
    setError(null);
    try {
      const quote = await getRandomQuote();
      setRandomQuote(quote);
    } catch (err: any) {
      console.error(err);
      setRandomQuote(null);
    } finally {
      setIsRandomLoading(false);
    }
  };

  const handleSearch = useCallback(async () => {
    if (!searchTerm.trim()) return;
    setIsLoading(true);
    setError(null);
    setQuotes([]);
    setCurrentView('search');

    try {
      const fetchedQuotes = await getPhilosophicalQuotes(searchTerm);
      if (fetchedQuotes.length === 0) {
        setError('Nenhum pensamento encontrado.');
        setIsLoading(false);
        return;
      }

      const quotesWithImagesPromises = fetchedQuotes.map(async (quote) => {
        const imageUrl = await generateQuoteImage(quote.quote);
        return { ...quote, imageUrl };
      });

      const resolvedQuotes = await Promise.all(quotesWithImagesPromises);
      setQuotes(resolvedQuotes);
    } catch (err: any) {
      setError(handleApiError(err));
    } finally {
      setIsLoading(false);
    }
  }, [searchTerm]);

  const handleRegenerateImage = async (quote: Quote) => {
    try {
      const newImageUrl = await generateQuoteImage(quote.quote);
      setQuotes(prev => prev.map(q => q.id === quote.id ? { ...q, imageUrl: newImageUrl } : q));
      if (randomQuote?.id === quote.id) setRandomQuote(prev => prev ? { ...prev, imageUrl: newImageUrl } : null);
      setFavorites(prev => prev.map(q => q.quote === quote.quote ? { ...q, imageUrl: newImageUrl } : q));
    } catch (err) {
      console.error("Erro ao trocar imagem:", err);
    }
  };

  const toggleFavorite = (quote: Quote) => {
    setFavorites(prev => {
      const exists = prev.some(fav => fav.quote === quote.quote);
      return exists ? prev.filter(fav => fav.quote !== quote.quote) : [quote, ...prev];
    });
  };

  return (
    <div className="bg-[#0a0c10] min-h-screen text-white flex justify-center p-0 sm:p-6">
      <div className="w-full max-w-lg h-screen sm:h-[92vh] bg-[#11141d] sm:rounded-[3rem] shadow-[0_0_100px_rgba(0,0,0,0.5)] flex flex-col overflow-hidden relative border border-white/5">

        {/* Header Elegante */}
        <header className="pt-10 pb-6 px-8 flex flex-col items-center">
          <div className="flex items-center gap-3 mb-8">
            <div className="p-2 bg-blue-500/10 rounded-xl">
              <SophiaIcon className="w-6 h-6 text-blue-400" />
            </div>
            <h1 className="text-xl font-bold tracking-[0.2em] text-gray-100">SOPHIA</h1>
          </div>

          <nav className="flex bg-[#1a1f2e] p-1.5 rounded-2xl w-full border border-white/5 shadow-inner">
             <button 
                onClick={() => setCurrentView('search')}
                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[11px] uppercase tracking-widest font-bold transition-all ${currentView === 'search' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}
             >
                <SearchIcon className="w-3.5 h-3.5" /> Explorar
             </button>
             <button 
                onClick={() => setCurrentView('favorites')}
                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[11px] uppercase tracking-widest font-bold transition-all ${currentView === 'favorites' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:text-gray-300'}`}
             >
                <BookmarkIcon className="w-3.5 h-3.5" fill={currentView === 'favorites'} /> Favoritos
             </button>
          </nav>
        </header>

        <main className="flex-1 overflow-y-auto px-8 pb-10 space-y-8 scroll-smooth scrollbar-hide">
          {currentView === 'favorites' ? (
            <div className="animate-fadeIn space-y-8">
                {favorites.length === 0 ? (
                    <div className="flex flex-col justify-center items-center py-32 text-center text-gray-600">
                        <BookmarkIcon className="w-16 h-16 opacity-5 mb-4" />
                        <p className="text-sm font-medium opacity-40 italic">Nenhum pensamento guardado ainda.</p>
                    </div>
                ) : (
                    <>
                        <div className="text-center">
                          <h2 className="font-serif-display text-2xl text-blue-100/60 italic">Sua Curadoria</h2>
                        </div>
                        {favorites.map((fav) => (
                            <QuoteCard key={fav.id} quote={fav} isFavorite={true} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </>
                )}
            </div>
          ) : (
            <div className="animate-fadeIn space-y-8">
                <div className="sticky top-0 z-20 bg-[#11141d]/80 backdrop-blur-md pb-2 pt-1">
                    <SearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} onSearch={handleSearch} isLoading={isLoading} />
                </div>

                {isLoading ? (
                    <div className="flex flex-col justify-center items-center py-24">
                      <Spinner />
                      <p className="mt-8 text-gray-500 text-[10px] uppercase tracking-[0.3em] font-bold animate-pulse">Consultando o Oráculo</p>
                    </div>
                ) : quotes.length > 0 ? (
                    <div className="space-y-10">
                        {quotes.map((quote, index) => (
                            <QuoteCard key={quote.id || index} quote={quote} isFavorite={favorites.some(f => f.quote === quote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </div>
                ) : error ? (
                    <div className="py-20 text-center px-6 border border-red-500/10 rounded-[2rem] bg-red-500/5">
                        <p className="text-red-400 text-sm font-medium mb-6">{error}</p>
                        <button onClick={fetchRandomQuote} className="px-8 py-3 bg-gray-800 rounded-full text-[10px] font-bold uppercase tracking-widest text-white">
                            Tentar Novamente
                        </button>
                    </div>
                ) : (
                    <div className="space-y-12">
                        {isRandomLoading ? (
                            <div className="flex flex-col justify-center items-center py-20">
                                <Spinner />
                                <p className="mt-6 text-[10px] text-gray-600 uppercase tracking-widest">Invocando Sabedoria</p>
                            </div>
                        ) : randomQuote && (
                            <div className="animate-slideUp flex flex-col">
                                <div className="flex items-center justify-between mb-6 px-1">
                                  <h2 className="font-serif-display text-xl text-gray-400 italic">Sugestão de hoje</h2>
                                  <button 
                                    onClick={fetchRandomQuote}
                                    className="p-3 rounded-full bg-white/5 hover:bg-white/10 text-blue-400 transition-all active:rotate-180 duration-500"
                                  >
                                    <RefreshIcon className="w-4 h-4" />
                                  </button>
                                </div>
                                <QuoteCard quote={randomQuote} isFavorite={favorites.some(f => f.quote === randomQuote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                            </div>
                        )}
                    </div>
                )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useState } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import { Spinner } from './Spinner';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      allowTaint: false,
      scale: 3,
      backgroundColor: '#000000',
      logging: false,
      ignoreElements: (element) => element.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const image = canvas.toDataURL("image/jpeg", 0.9);
      const link = document.createElement('a');
      link.download = `sophia-thought.jpg`;
      link.href = image;
      link.click();
    } catch (error) {
      console.error(error);
    } finally {
      setIsDownloading(false);
    }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsSharing(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-quote.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'Sophia: Pensamentos',
        });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Texto copiado com sucesso!');
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsSharing(false);
    }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    setIsImageLoaded(false);
    try {
      await onRegenerateImage(quote);
    } finally {
      setIsRegenerating(false);
    }
  };

  return (
    <div className="space-y-6 group">
      <div 
        ref={cardRef} 
        className="relative w-full aspect-[4/5] sm:aspect-[9/16] rounded-[2.5rem] overflow-hidden shadow-[0_20px_50px_rgba(0,0,0,0.6)] bg-black border border-white/5 flex flex-col"
      >
        {/* Background Image with Overlay */}
        {quote.imageUrl ? (
            <img 
                src={quote.imageUrl} 
                alt="Background" 
                onLoad={() => setIsImageLoaded(true)}
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-1000 ${isImageLoaded ? 'opacity-60 scale-100' : 'opacity-0 scale-110'}`}
            />
        ) : (
          <div className="absolute inset-0 bg-gradient-to-br from-gray-900 to-black opacity-50"></div>
        )}

        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-black/20 z-0"></div>

        {/* Quote Content */}
        <div className="absolute inset-0 flex flex-col justify-center px-10 sm:px-12 text-center z-10 pointer-events-none">
            <span className="w-10 h-[1px] bg-blue-400/50 mx-auto mb-8 rounded-full"></span>
            <blockquote className="font-serif-display text-2xl sm:text-4xl font-medium leading-[1.3] tracking-wide italic text-gray-50 mb-8 break-words">
                “{quote.quote}”
            </blockquote>
            <cite className="font-serif-display text-lg sm:text-xl text-blue-200/80 not-italic block uppercase tracking-widest">
                {quote.author}
            </cite>
        </div>

        {/* Top Floating Controls */}
        <div className="exclude-from-capture absolute top-6 right-6 flex flex-col gap-3 z-30">
            <button
                onClick={onImageChange}
                disabled={isRegenerating}
                className="p-3.5 rounded-full bg-black/40 backdrop-blur-2xl border border-white/10 hover:bg-black/60 transition-all active:scale-90"
            >
                <RefreshIcon className={`w-5 h-5 text-white/90 ${isRegenerating ? 'animate-spin text-blue-400' : ''}`} />
            </button>
            <button
                onClick={() => onToggleFavorite?.(quote)}
                className="p-3.5 rounded-full bg-black/40 backdrop-blur-2xl border border-white/10 hover:bg-black/60 transition-all active:scale-90"
            >
                <HeartIcon className={`w-5 h-5 ${isFavorite ? 'text-red-500 fill-red-500' : 'text-white/90'}`} fill={isFavorite} />
            </button>
        </div>

        {/* Branding Footer (Invisible on UI, visible on capture) */}
        <div className="absolute bottom-8 left-0 right-0 text-center opacity-30 text-[9px] uppercase tracking-[0.4em] font-bold text-white z-10">
            Sophia • Sabedoria Artificial
        </div>

        {/* Loading Overlay */}
        {(isRegenerating || !isImageLoaded) && (
            <div className="absolute inset-0 bg-[#0a0c10]/95 flex flex-col items-center justify-center z-40 backdrop-blur-sm">
                <Spinner />
                <span className="text-[9px] text-gray-500 mt-6 uppercase tracking-[0.3em] font-bold animate-pulse">Refinando Imagem</span>
            </div>
        )}
      </div>

      {/* Action Buttons Below Card */}
      <div className="flex gap-4">
            <button
                onClick={handleShare}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-white text-black font-bold py-5 rounded-3xl flex items-center justify-center gap-3 transition-all active:scale-95 hover:bg-gray-100 text-[11px] uppercase tracking-widest shadow-lg shadow-white/5"
            >
                <ShareIcon className="w-4 h-4" /> Enviar
            </button>
            <button
                onClick={handleDownload}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-[#1a1f2e] text-white font-bold py-5 rounded-3xl flex items-center justify-center gap-3 transition-all active:scale-95 hover:bg-[#252b3d] text-[11px] uppercase tracking-widest border border-white/5 shadow-lg shadow-black/20"
            >
                <DownloadIcon className="w-4 h-4" /> Salvar
            </button>
      </div>
    </div>
  );
};

