import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import type { Quote } from '../types';

const FALLBACK_IMAGES = [
  "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?q=80&w=1080&auto=format&fit=crop", // Campo ensolarado
  "https://images.unsplash.com/photo-1499002238440-d264edd596ec?q=80&w=1080&auto=format&fit=crop", // Lavanda sob sol
  "https://images.unsplash.com/photo-1500382017468-9049fed747ef?q=80&w=1080&auto=format&fit=crop", // Montanha luminosa
  "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?q=80&w=1080&auto=format&fit=crop", // Floresta com raios de sol
  "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?q=80&w=1080&auto=format&fit=crop"  // Céu claro
];

const getRandomFallbackImage = () => FALLBACK_IMAGES[Math.floor(Math.random() * FALLBACK_IMAGES.length)];
const generateId = () => Date.now().toString(36) + Math.random().toString(36).substring(2);

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function withRetry<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const errorMsg = error?.message?.toLowerCase() || "";
    const isRetryable = errorMsg.includes('overloaded') || errorMsg.includes('503') || errorMsg.includes('unavailable') || errorMsg.includes('429');

    if (isRetryable && retries > 0) {
      await sleep(delay);
      return withRetry(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

const cleanJsonString = (str: string | undefined): string => {
  if (!str) return "{}";
  let cleaned = str.trim();
  cleaned = cleaned.replace(/^```json\s*/, "").replace(/```$/, "").trim();
  return cleaned;
};

export async function getPhilosophicalQuotes(theme: string): Promise<Quote[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-3-flash-preview", 
    contents: `Gere um array JSON com 3 citações curtas e profundas em Português sobre o tema '${theme}'. Use filósofos reais e renomados.`,
    config: {
      responseMimeType: "application/json",
      thinkingConfig: { thinkingBudget: 0 },
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            quote: { type: Type.STRING },
            author: { type: Type.STRING },
          },
          required: ["quote", "author"],
        }
      },
    },
  }));

  try {
    const jsonString = cleanJsonString(response.text);
    const quotesRaw = JSON.parse(jsonString);
    return quotesRaw.map((q: any) => ({ ...q, id: generateId(), imageUrl: '' }));
  } catch (e) {
    console.error("Erro no parse de citações:", e);
    return [];
  }
}

export async function getRandomQuote(): Promise<Quote> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Gere uma citação filosófica aleatória, curta e poderosa em Português. Varie entre temas como ética, metafísica, tempo e existência. Retorne em formato JSON.`,
    config: {
      responseMimeType: "application/json",
      thinkingConfig: { thinkingBudget: 0 },
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          quote: { type: Type.STRING },
          author: { type: Type.STRING },
        },
        required: ["quote", "author"],
      },
    },
  }));

  const jsonString = cleanJsonString(response.text);
  const dailyQuoteRaw = JSON.parse(jsonString);
  const imageUrl = await generateQuoteImage(dailyQuoteRaw.quote);
  return { ...dailyQuoteRaw, id: generateId(), imageUrl };
}

export async function generateQuoteImage(quoteText: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const analysisResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analise a frase: "${quoteText}". 
      Crie um prompt visual curto para uma IA de imagem que represente essa ideia de forma metafórica e ILUMINADA.
      REGRAS CRÍTICAS: 
      - NUNCA inclua pessoas ou silhuetas.
      - FOQUE em: Natureza ensolarada, arquitetura branca, luz da manhã, nuvens claras, cores pastéis e brilhantes.
      - AMBIENTE: Radiante, calmo, aberto, high-key lighting. Evite sombras pesadas.
      Responda apenas com o prompt em inglês.`,
      config: { thinkingConfig: { thinkingBudget: 0 } }
    }));

    const visualPrompt = analysisResponse.text || "Bright ethereal landscape, soft daylight, minimalist zen garden";

    const imageResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `${visualPrompt}. Soft daylight, bright colors, bright morning sun, ethereal atmosphere, airy composition. STRICTLY NO HUMANS, NO PEOPLE. Clear bright scenery, white marble architecture or sunny meadows. High key lighting, 9:16 vertical.` }] },
      config: {
        imageConfig: { aspectRatio: "9:16" }
      },
    }));

    let base64Image: string | null = null;
    if (imageResponse.candidates?.[0]?.content?.parts) {
      for (const part of imageResponse.candidates[0].content.parts) {
        if (part.inlineData?.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (base64Image) {
      return `data:image/jpeg;base64,${base64Image}`;
    }
    throw new Error("Falha na geração da imagem");

  } catch (error) {
    console.warn("Recorrendo a imagem de fallback...");
    return getRandomFallbackImage();
  }
}

import React, { useState, useCallback, useEffect } from 'react';
import { SearchBar } from './components/SearchBar';
import { QuoteCard } from './components/QuoteCard';
import { Spinner } from './components/Spinner';
import { getPhilosophicalQuotes, getRandomQuote, generateQuoteImage } from './services/geminiService';
import type { Quote } from './types';
import { SophiaIcon, SearchIcon, BookmarkIcon, RefreshIcon } from './components/Icons';

type ViewState = 'search' | 'favorites';

const App: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [randomQuote, setRandomQuote] = useState<Quote | null>(null);
  const [isRandomLoading, setIsRandomLoading] = useState<boolean>(true);

  const [favorites, setFavorites] = useState<Quote[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('search');

  useEffect(() => {
    const savedFavorites = localStorage.getItem('sophia_favorites');
    if (savedFavorites) {
      try {
        setFavorites(JSON.parse(savedFavorites));
      } catch (e) {
        console.error("Erro ao carregar favoritos", e);
      }
    }
    fetchRandomQuote();
  }, []);

  useEffect(() => {
    localStorage.setItem('sophia_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const handleApiError = (err: any) => {
    console.error("Erro na App:", err);
    return "Um momento de silêncio para a sabedoria carregar.";
  };

  const fetchRandomQuote = async () => {
    setIsRandomLoading(true);
    setError(null);
    try {
      const quote = await getRandomQuote();
      setRandomQuote(quote);
    } catch (err: any) {
      console.error(err);
      setRandomQuote(null);
    } finally {
      setIsRandomLoading(false);
    }
  };

  const handleSearch = useCallback(async () => {
    if (!searchTerm.trim()) return;
    setIsLoading(true);
    setError(null);
    setQuotes([]);
    setCurrentView('search');

    try {
      const fetchedQuotes = await getPhilosophicalQuotes(searchTerm);
      if (fetchedQuotes.length === 0) {
        setError('Nenhum pensamento encontrado.');
        setIsLoading(false);
        return;
      }

      const quotesWithImagesPromises = fetchedQuotes.map(async (quote) => {
        const imageUrl = await generateQuoteImage(quote.quote);
        return { ...quote, imageUrl };
      });

      const resolvedQuotes = await Promise.all(quotesWithImagesPromises);
      setQuotes(resolvedQuotes);
    } catch (err: any) {
      setError(handleApiError(err));
    } finally {
      setIsLoading(false);
    }
  }, [searchTerm]);

  const handleRegenerateImage = async (quote: Quote) => {
    try {
      const newImageUrl = await generateQuoteImage(quote.quote);
      setQuotes(prev => prev.map(q => q.id === quote.id ? { ...q, imageUrl: newImageUrl } : q));
      if (randomQuote?.id === quote.id) setRandomQuote(prev => prev ? { ...prev, imageUrl: newImageUrl } : null);
      setFavorites(prev => prev.map(q => q.quote === quote.quote ? { ...q, imageUrl: newImageUrl } : q));
    } catch (err) {
      console.error("Erro ao trocar imagem:", err);
    }
  };

  const toggleFavorite = (quote: Quote) => {
    setFavorites(prev => {
      const exists = prev.some(fav => fav.quote === quote.quote);
      return exists ? prev.filter(fav => fav.quote !== quote.quote) : [quote, ...prev];
    });
  };

  return (
    <div className="bg-[#f0f2f5] min-h-screen text-gray-900 flex justify-center p-0 sm:p-6">
      <div className="w-full max-w-lg h-screen sm:h-[92vh] bg-white sm:rounded-[3rem] shadow-[0_20px_80px_rgba(0,0,0,0.1)] flex flex-col overflow-hidden relative border border-white">

        {/* Header Claro e Minimalista */}
        <header className="pt-10 pb-6 px-8 flex flex-col items-center">
          <div className="flex items-center gap-3 mb-8">
            <div className="p-2 bg-blue-500/10 rounded-xl">
              <SophiaIcon className="w-6 h-6 text-blue-600" />
            </div>
            <h1 className="text-xl font-bold tracking-[0.2em] text-gray-800">SOPHIA</h1>
          </div>

          <nav className="flex bg-gray-100 p-1.5 rounded-2xl w-full border border-gray-200 shadow-sm">
             <button 
                onClick={() => setCurrentView('search')}
                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[11px] uppercase tracking-widest font-bold transition-all ${currentView === 'search' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
             >
                <SearchIcon className="w-3.5 h-3.5" /> Explorar
             </button>
             <button 
                onClick={() => setCurrentView('favorites')}
                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[11px] uppercase tracking-widest font-bold transition-all ${currentView === 'favorites' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
             >
                <BookmarkIcon className="w-3.5 h-3.5" fill={currentView === 'favorites'} /> Favoritos
             </button>
          </nav>
        </header>

        <main className="flex-1 overflow-y-auto px-8 pb-10 space-y-8 scroll-smooth scrollbar-hide">
          {currentView === 'favorites' ? (
            <div className="animate-fadeIn space-y-8">
                {favorites.length === 0 ? (
                    <div className="flex flex-col justify-center items-center py-32 text-center text-gray-300">
                        <BookmarkIcon className="w-16 h-16 opacity-10 mb-4" />
                        <p className="text-sm font-medium italic">Sua biblioteca está vazia.</p>
                    </div>
                ) : (
                    <>
                        <div className="text-center">
                          <h2 className="font-serif-display text-2xl text-gray-800 italic">Curadoria de Luz</h2>
                        </div>
                        {favorites.map((fav) => (
                            <QuoteCard key={fav.id} quote={fav} isFavorite={true} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </>
                )}
            </div>
          ) : (
            <div className="animate-fadeIn space-y-8">
                <div className="sticky top-0 z-20 bg-white/80 backdrop-blur-md pb-2 pt-1">
                    <SearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} onSearch={handleSearch} isLoading={isLoading} />
                </div>

                {isLoading ? (
                    <div className="flex flex-col justify-center items-center py-24">
                      <Spinner />
                      <p className="mt-8 text-gray-400 text-[10px] uppercase tracking-[0.3em] font-bold animate-pulse">Consultando a Luz</p>
                    </div>
                ) : quotes.length > 0 ? (
                    <div className="space-y-10">
                        {quotes.map((quote, index) => (
                            <QuoteCard key={quote.id || index} quote={quote} isFavorite={favorites.some(f => f.quote === quote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </div>
                ) : error ? (
                    <div className="py-16 text-center px-6 border border-blue-100 rounded-[2rem] bg-blue-50/50">
                        <p className="text-gray-600 text-sm font-medium mb-6">{error}</p>
                        <button onClick={fetchRandomQuote} className="px-8 py-3 bg-white border border-gray-200 shadow-sm rounded-full text-[10px] font-bold uppercase tracking-widest text-gray-600">
                            Tentar Novamente
                        </button>
                    </div>
                ) : (
                    <div className="space-y-12">
                        {isRandomLoading ? (
                            <div className="flex flex-col justify-center items-center py-20">
                                <Spinner />
                                <p className="mt-6 text-[10px] text-gray-400 uppercase tracking-widest">Invocando Sabedoria</p>
                            </div>
                        ) : randomQuote && (
                            <div className="animate-slideUp flex flex-col">
                                <div className="flex items-center justify-between mb-6 px-1">
                                  <h2 className="font-serif-display text-xl text-gray-800 italic">Inspiração</h2>
                                  <button 
                                    onClick={fetchRandomQuote}
                                    className="p-3 rounded-full bg-gray-50 hover:bg-gray-100 text-blue-500 transition-all shadow-sm"
                                  >
                                    <RefreshIcon className="w-4 h-4" />
                                  </button>
                                </div>
                                <QuoteCard quote={randomQuote} isFavorite={favorites.some(f => f.quote === randomQuote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                            </div>
                        )}
                    </div>
                )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useState } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import { Spinner } from './Spinner';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      allowTaint: false,
      scale: 3,
      backgroundColor: '#FFFFFF',
      logging: false,
      ignoreElements: (element) => element.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const image = canvas.toDataURL("image/jpeg", 0.9);
      const link = document.createElement('a');
      link.download = `sophia-thought.jpg`;
      link.href = image;
      link.click();
    } catch (error) {
      console.error(error);
    } finally {
      setIsDownloading(false);
    }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsSharing(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-quote.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'Sophia: Pensamentos',
        });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Copiado para a área de transferência!');
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsSharing(false);
    }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    setIsImageLoaded(false);
    try {
      await onRegenerateImage(quote);
    } finally {
      setIsRegenerating(false);
    }
  };

  return (
    <div className="space-y-6 group">
      <div 
        ref={cardRef} 
        className="relative w-full aspect-[4/5] sm:aspect-[9/16] rounded-[2.5rem] overflow-hidden shadow-[0_30px_60px_rgba(0,0,0,0.08)] bg-gray-50 border border-gray-100 flex flex-col"
      >
        {/* Imagem de Fundo com Overlay Suave */}
        {quote.imageUrl ? (
            <img 
                src={quote.imageUrl} 
                alt="Background" 
                onLoad={() => setIsImageLoaded(true)}
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-1000 ${isImageLoaded ? 'opacity-80 scale-100' : 'opacity-0 scale-110'}`}
            />
        ) : (
          <div className="absolute inset-0 bg-gradient-to-br from-blue-50 to-white"></div>
        )}

        {/* Gradiente para garantir legibilidade do texto claro sobre fundos claros */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/30 z-0"></div>

        {/* Conteúdo da Citação com Contraste */}
        <div className="absolute inset-0 flex flex-col justify-center px-10 sm:px-12 text-center z-10 pointer-events-none">
            <span className="w-10 h-[1.5px] bg-white/60 mx-auto mb-8 rounded-full shadow-sm"></span>
            <blockquote className="font-serif-display text-2xl sm:text-4xl font-bold leading-[1.3] tracking-wide italic text-white drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)] mb-8 break-words">
                “{quote.quote}”
            </blockquote>
            <cite className="font-serif-display text-lg sm:text-xl text-white/90 drop-shadow-[0_1px_2px_rgba(0,0,0,0.5)] not-italic block uppercase tracking-widest font-bold">
                {quote.author}
            </cite>
        </div>

        {/* Controles Flutuantes (Claros) */}
        <div className="exclude-from-capture absolute top-6 right-6 flex flex-col gap-3 z-30">
            <button
                onClick={onImageChange}
                disabled={isRegenerating}
                className="p-3.5 rounded-full bg-white/60 backdrop-blur-xl border border-white/40 hover:bg-white/90 shadow-sm transition-all active:scale-90"
            >
                <RefreshIcon className={`w-5 h-5 text-blue-600 ${isRegenerating ? 'animate-spin' : ''}`} />
            </button>
            <button
                onClick={() => onToggleFavorite?.(quote)}
                className="p-3.5 rounded-full bg-white/60 backdrop-blur-xl border border-white/40 hover:bg-white/90 shadow-sm transition-all active:scale-90"
            >
                <HeartIcon className={`w-5 h-5 ${isFavorite ? 'text-red-500 fill-red-500' : 'text-gray-600'}`} fill={isFavorite} />
            </button>
        </div>

        {/* Rodapé da Marca */}
        <div className="absolute bottom-8 left-0 right-0 text-center opacity-40 text-[9px] uppercase tracking-[0.4em] font-bold text-white drop-shadow-md z-10">
            Sophia • Sabedoria Artificial
        </div>

        {/* Overlay de Carregamento Luminoso */}
        {(isRegenerating || !isImageLoaded) && (
            <div className="absolute inset-0 bg-white/80 flex flex-col items-center justify-center z-40 backdrop-blur-md">
                <Spinner />
                <span className="text-[9px] text-blue-400 mt-6 uppercase tracking-[0.3em] font-bold animate-pulse">Iluminando Pensamento</span>
            </div>
        )}
      </div>

      {/* Botões de Ação Luminosos */}
      <div className="flex gap-4">
            <button
                onClick={handleShare}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-blue-600 text-white font-bold py-5 rounded-3xl flex items-center justify-center gap-3 transition-all active:scale-95 hover:bg-blue-700 text-[11px] uppercase tracking-widest shadow-lg shadow-blue-500/20"
            >
                <ShareIcon className="w-4 h-4" /> Enviar
            </button>
            <button
                onClick={handleDownload}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-white text-gray-700 font-bold py-5 rounded-3xl flex items-center justify-center gap-3 transition-all active:scale-95 hover:bg-gray-50 text-[11px] uppercase tracking-widest border border-gray-200 shadow-md shadow-gray-100"
            >
                <DownloadIcon className="w-4 h-4" /> Salvar
            </button>
      </div>
    </div>
  );
};

