import React, { useRef, useState } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import { Spinner } from './Spinner';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    // Captura com alta qualidade para compartilhamento
    return await html2canvas(cardRef.current, {
      useCORS: true,
      scale: 3,
      backgroundColor: '#0d1117',
      logging: false,
      ignoreElements: (el) => el.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const link = document.createElement('a');
      link.download = `sophia-quote.jpg`;
      link.href = canvas.toDataURL("image/jpeg", 0.95);
      link.click();
    } finally { setIsDownloading(false); }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsSharing(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: 'Pensamento Sophia' });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Copiado para a área de transferência!');
      }
    } finally { setIsSharing(false); }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    setIsImageLoaded(false);
    try { await onRegenerateImage(quote); } finally { setIsRegenerating(false); }
  };

  return (
    <div className="space-y-6 group animate-fadeIn">
      <div 
        ref={cardRef} 
        className="relative w-full aspect-[4/5] sm:aspect-[9/16] rounded-[3rem] overflow-hidden shadow-[0_50px_100px_rgba(0,0,0,0.7)] bg-[#111] border border-white/5 flex flex-col"
      >
        {/* Background Layer */}
        {quote.imageUrl ? (
            <img 
                src={quote.imageUrl} 
                alt="Background" 
                onLoad={() => setIsImageLoaded(true)}
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-1000 ${isImageLoaded ? 'opacity-100 scale-100 blur-0' : 'opacity-0 scale-110 blur-xl'}`}
            />
        ) : <div className="absolute inset-0 bg-[#0d1117]"></div>}

        {/* Readability Overlays */}
        {/* Superior: darker for control icons */}
        <div className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-black/40 to-transparent z-10"></div>

        {/* Central: light diffuse glow to separate text from background without looking "dirty" */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-10">
          <div className="w-[80%] h-[40%] bg-black/10 blur-[80px] rounded-full"></div>
        </div>

        {/* Inferior: stronger for author and footer */}
        <div className="absolute inset-x-0 bottom-0 h-64 bg-gradient-to-t from-black/60 via-black/20 to-transparent z-10"></div>

        {/* Main Content */}
        <div className="absolute inset-0 flex flex-col justify-center px-10 sm:px-14 text-center z-20 pointer-events-none">
            {/* Visual Accent */}
            <div className="w-12 h-1 bg-blue-500/80 mx-auto mb-10 rounded-full shadow-[0_0_20px_rgba(59,130,246,0.6)]"></div>

            <blockquote 
              className="font-serif-display text-2xl sm:text-4xl font-bold leading-tight tracking-tight italic text-white mb-10"
              style={{ 
                textShadow: '0 4px 16px rgba(0,0,0,0.9), 0 2px 4px rgba(0,0,0,0.6)',
                letterSpacing: '-0.02em'
              }}
            >
                “{quote.quote}”
            </blockquote>

            <cite 
              className="font-serif-display text-xl sm:text-2xl text-blue-200/90 not-italic block uppercase tracking-[0.25em] font-medium"
              style={{ textShadow: '0 2px 8px rgba(0,0,0,1)' }}
            >
                {quote.author}
            </cite>
        </div>

        {/* Floating Controls */}
        <div className="exclude-from-capture absolute top-8 right-8 flex flex-col gap-4 z-30">
            <button
                onClick={onImageChange}
                disabled={isRegenerating}
                className="p-4 rounded-full bg-black/40 backdrop-blur-2xl border border-white/10 hover:bg-black/60 transition-all active:scale-90 shadow-2xl group/btn"
                title="Novo cenário"
            >
                <RefreshIcon className={`w-5 h-5 text-white transition-all ${isRegenerating ? 'animate-spin text-blue-400' : 'group-hover/btn:rotate-180'}`} />
            </button>
            <button
                onClick={() => onToggleFavorite?.(quote)}
                className="p-4 rounded-full bg-black/40 backdrop-blur-2xl border border-white/10 hover:bg-black/60 transition-all active:scale-90 shadow-2xl"
                title="Favoritar"
            >
                <HeartIcon className={`w-5 h-5 transition-all ${isFavorite ? 'text-red-500 fill-red-500 scale-110' : 'text-white'}`} fill={isFavorite} />
            </button>
        </div>

        {/* Branding Footer */}
        <div className="absolute bottom-12 left-0 right-0 text-center opacity-80 text-[11px] uppercase tracking-[0.7em] font-black text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)] z-20">
            SOPHIA
        </div>

        {/* Loading/Regenerating State */}
        {(isRegenerating || !isImageLoaded) && (
            <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center z-50 backdrop-blur-xl">
                <Spinner />
                <span className="text-[11px] text-blue-400 mt-8 uppercase tracking-[0.5em] font-bold animate-pulse">Tecendo Pensamento...</span>
            </div>
        )}
      </div>

      {/* Action Bar style messaging app */}
      <div className="flex gap-4 px-2">
            <button
                onClick={handleShare}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-[3] bg-blue-600 hover:bg-blue-500 text-white font-black py-5 rounded-[2.5rem] flex items-center justify-center gap-3 transition-all active:scale-95 shadow-[0_15px_40px_rgba(37,99,235,0.4)] text-[13px] uppercase tracking-widest"
            >
                {isSharing ? <Spinner className="w-4 h-4 text-white" /> : <ShareIcon className="w-5 h-5" />}
                {isSharing ? 'Preparando...' : 'Compartilhar'}
            </button>
            <button
                onClick={handleDownload}
                disabled={isSharing || isDownloading || isRegenerating}
                className="flex-1 bg-[#1a1f26] hover:bg-[#252b36] text-white font-bold py-5 rounded-[2.5rem] flex items-center justify-center transition-all active:scale-95 border border-white/5 shadow-2xl"
                title="Baixar imagem"
            >
                {isDownloading ? <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin"></div> : <DownloadIcon className="w-6 h-6" />}
            </button>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { SearchBar } from './components/SearchBar';
import { QuoteCard } from './components/QuoteCard';
import { Spinner } from './components/Spinner';
import { getPhilosophicalQuotes, getRandomQuote, generateQuoteImage } from './services/geminiService';
import type { Quote } from './types';
import { SophiaIcon, SearchIcon, BookmarkIcon, RefreshIcon } from './components/Icons';

type ViewState = 'search' | 'favorites';

const App: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [randomQuote, setRandomQuote] = useState<Quote | null>(null);
  const [isRandomLoading, setIsRandomLoading] = useState<boolean>(true);

  const [favorites, setFavorites] = useState<Quote[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('search');

  useEffect(() => {
    const savedFavorites = localStorage.getItem('sophia_favorites');
    if (savedFavorites) {
      try {
        setFavorites(JSON.parse(savedFavorites));
      } catch (e) { console.error(e); }
    }
    fetchRandomQuote();
  }, []);

  useEffect(() => {
    localStorage.setItem('sophia_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const fetchRandomQuote = async () => {
    setIsRandomLoading(true);
    setError(null);
    try {
      const quote = await getRandomQuote();
      setRandomQuote(quote);
    } catch (err: any) {
      setRandomQuote(null);
    } finally {
      setIsRandomLoading(false);
    }
  };

  const handleSearch = useCallback(async () => {
    if (!searchTerm.trim()) return;
    setIsLoading(true);
    setError(null);
    setQuotes([]);
    setCurrentView('search');

    try {
      const fetchedQuotes = await getPhilosophicalQuotes(searchTerm);
      if (fetchedQuotes.length === 0) {
        setError('Nenhum pensamento encontrado.');
        setIsLoading(false);
        return;
      }

      const quotesWithImagesPromises = fetchedQuotes.map(async (quote) => {
        const imageUrl = await generateQuoteImage(quote.quote);
        return { ...quote, imageUrl };
      });

      const resolvedQuotes = await Promise.all(quotesWithImagesPromises);
      setQuotes(resolvedQuotes);
    } catch (err: any) {
      setError("Ocorreu um erro ao buscar sabedoria.");
    } finally {
      setIsLoading(false);
    }
  }, [searchTerm]);

  const handleRegenerateImage = async (quote: Quote) => {
    try {
      const newImageUrl = await generateQuoteImage(quote.quote);
      setQuotes(prev => prev.map(q => q.id === quote.id ? { ...q, imageUrl: newImageUrl } : q));
      if (randomQuote?.id === quote.id) setRandomQuote(prev => prev ? { ...prev, imageUrl: newImageUrl } : null);
      setFavorites(prev => prev.map(q => q.quote === quote.quote ? { ...q, imageUrl: newImageUrl } : q));
    } catch (err) { console.error(err); }
  };

  const toggleFavorite = (quote: Quote) => {
    setFavorites(prev => {
      const exists = prev.some(fav => fav.quote === quote.quote);
      return exists ? prev.filter(fav => fav.quote !== quote.quote) : [quote, ...prev];
    });
  };

  return (
    <div className="bg-[#050608] min-h-screen text-white flex justify-center p-0 sm:p-6 selection:bg-blue-500/30">
      <div className="w-full max-w-lg h-screen sm:h-[92vh] bg-[#0a0c10] sm:rounded-[3.5rem] shadow-[0_0_150px_rgba(0,0,0,0.8)] flex flex-col overflow-hidden relative border border-white/5">

        <header className="pt-12 pb-8 px-10 flex flex-col items-center">
          <div className="flex items-center gap-4 mb-10">
            <div className="p-2.5 bg-blue-500/15 rounded-2xl ring-1 ring-blue-500/20">
              <SophiaIcon className="w-7 h-7 text-blue-400" />
            </div>
            <h1 className="text-2xl font-black tracking-[0.25em] text-white">SOPHIA</h1>
          </div>

          <nav className="flex bg-[#12161d] p-1.5 rounded-[2rem] w-full border border-white/5 shadow-2xl">
             <button 
                onClick={() => setCurrentView('search')}
                className={`flex-1 flex items-center justify-center gap-2.5 py-4 rounded-[1.8rem] text-[12px] uppercase tracking-widest font-black transition-all duration-300 ${currentView === 'search' ? 'bg-blue-600 text-white shadow-[0_10px_25px_rgba(37,99,235,0.4)]' : 'text-gray-500 hover:text-gray-300'}`}
             >
                <SearchIcon className="w-4 h-4" /> Explorar
             </button>
             <button 
                onClick={() => setCurrentView('favorites')}
                className={`flex-1 flex items-center justify-center gap-2.5 py-4 rounded-[1.8rem] text-[12px] uppercase tracking-widest font-black transition-all duration-300 ${currentView === 'favorites' ? 'bg-blue-600 text-white shadow-[0_10px_25px_rgba(37,99,235,0.4)]' : 'text-gray-500 hover:text-gray-300'}`}
             >
                <BookmarkIcon className="w-4 h-4" fill={currentView === 'favorites'} /> Favoritos
             </button>
          </nav>
        </header>

        <main className="flex-1 overflow-y-auto px-10 pb-12 space-y-10 scrollbar-hide">
          {currentView === 'favorites' ? (
            <div className="animate-fadeIn space-y-10">
                {favorites.length === 0 ? (
                    <div className="flex flex-col justify-center items-center py-40 text-center opacity-30">
                        <BookmarkIcon className="w-20 h-20 mb-6" />
                        <p className="text-sm font-medium tracking-widest uppercase italic">Nenhuma curadoria ainda.</p>
                    </div>
                ) : (
                    <>
                        <h2 className="text-center font-serif-display text-2xl text-blue-100/30 italic pb-2">Coleção de Pensamentos</h2>
                        {favorites.map((fav) => (
                            <QuoteCard key={fav.id} quote={fav} isFavorite={true} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </>
                )}
            </div>
          ) : (
            <div className="animate-fadeIn space-y-10">
                <div className="sticky top-0 z-20 bg-[#0a0c10]/80 backdrop-blur-xl pb-4 pt-1">
                    <SearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} onSearch={handleSearch} isLoading={isLoading} />
                </div>

                {isLoading ? (
                    <div className="flex flex-col justify-center items-center py-32">
                      <Spinner className="w-12 h-12" />
                      <p className="mt-10 text-blue-400 text-[11px] uppercase tracking-[0.4em] font-black animate-pulse">Consultando Oráculo</p>
                    </div>
                ) : quotes.length > 0 ? (
                    <div className="space-y-14">
                        {quotes.map((quote, index) => (
                            <QuoteCard key={quote.id || index} quote={quote} isFavorite={favorites.some(f => f.quote === quote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </div>
                ) : (
                    <div className="space-y-12">
                        {isRandomLoading ? (
                            <div className="flex flex-col justify-center items-center py-24">
                                <Spinner className="w-10 h-10" />
                                <p className="mt-8 text-[11px] text-gray-600 uppercase tracking-widest font-bold">Respirando fundo...</p>
                            </div>
                        ) : randomQuote && (
                            <div className="animate-slideUp flex flex-col">
                                <div className="flex items-center justify-between mb-8 px-2">
                                  <h2 className="font-serif-display text-2xl text-gray-400 italic">Sugestão do Dia</h2>
                                  <button onClick={fetchRandomQuote} className="p-3.5 rounded-full bg-white/5 hover:bg-white/10 text-blue-400 transition-all border border-white/5 active:rotate-180 duration-500">
                                    <RefreshIcon className="w-5 h-5" />
                                  </button>
                                </div>
                                <QuoteCard quote={randomQuote} isFavorite={favorites.some(f => f.quote === randomQuote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                            </div>
                        )}
                    </div>
                )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

