async function fetchPexelsImage(query: string): Promise<string | null> {
  const pexelsApiKey = process.env.PEXELS_API_KEY;
  if (!pexelsApiKey) return null;

  try {
    const response = await fetch(`https://api.pexels.com/v1/search?query=${encodeURIComponent(query)}&per_page=1&orientation=portrait`, {
      headers: { Authorization: pexelsApiKey }
    });
    const data = await response.json();
    return data.photos?.[0]?.src?.large2x || null;
  } catch (error) {
    console.error("Pexels error:", error);
    return null;
  }
}

export async function generateQuoteImage(quoteText: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // 1. Analisar frase e gerar prompt para IA + keywords para Pexels
    const analysisResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analise a frase: "${quoteText}".
      Retorne um JSON com:
      1. visualPrompt: Prompt em inglês para geração de imagem (Moody, Chiaroscuro style).
      2. searchKeyword: 2 ou 3 palavras em inglês para busca de fotos (ex: "misty forest", "ancient library").`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualPrompt: { type: Type.STRING },
            searchKeyword: { type: Type.STRING },
          },
          required: ["visualPrompt", "searchKeyword"]
        }
      }
    }));

    const analysis = JSON.parse(analysisResponse.text);
    const visualPrompt = analysis.visualPrompt;
    const searchKeyword = analysis.searchKeyword;

    // Tentativa Nível 1: Geração via Gemini
    try {
      const imageResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: `Cinematic photography of ${visualPrompt}. High contrast, deep shadows, 8k, moody atmosphere. 9:16 aspect ratio.` }] },
        config: { imageConfig: { aspectRatio: "9:16" } },
      }));

      if (imageResponse.candidates?.[0]?.content?.parts) {
        for (const part of imageResponse.candidates[0].content.parts) {
          if (part.inlineData?.data) {
            return `data:image/jpeg;base64,${part.inlineData.data}`;
          }
        }
      }
    } catch (genError) {
      console.warn("Gemini Image Gen failed, trying Pexels...", genError);
    }

    // Tentativa Nível 2: Busca no Pexels
    const pexelsUrl = await fetchPexelsImage(searchKeyword);
    if (pexelsUrl) return pexelsUrl;

    // Tentativa Nível 3: Fallback estático
    return getRandomFallbackImage();

  } catch (error) {
    console.error("Critical image generation error:", error);
    return getRandomFallbackImage();
  }
}

