async function fetchPexelsImage(query: string): Promise<string | null> {
  const pexelsApiKey = process.env.PEXELS_API_KEY;
  if (!pexelsApiKey) return null;

  try {
    const safeQuery = `${query} landscape architecture minimalist -person -people`;
    const response = await fetch(`https://api.pexels.com/v1/search?query=${encodeURIComponent(safeQuery)}&per_page=1&orientation=portrait`, {
      headers: { Authorization: pexelsApiKey }
    });
    const data = await response.json();
    return data.photos?.[0]?.src?.large2x || null;
  } catch (error) {
    console.error("Pexels error:", error);
    return null;
  }
}

export async function generateQuoteImage(quoteText: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // 1. ANÁLISE CONTEXTUAL
    const analysisResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analise o sentimento desta frase: "${quoteText}".
      Retorne um JSON com:
      1. visualPrompt: A poetic description for image generation (English). Focus on textures, landscapes, objects or abstract light.
      2. searchKeywords: 3 English keywords for high-end photography search.
      IMPORTANT: STRICTLY NO HUMANS, NO FACES, NO BODY PARTS.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualPrompt: { type: Type.STRING },
            searchKeywords: { type: Type.STRING },
          },
          required: ["visualPrompt", "searchKeywords"]
        }
      }
    }));

    const { visualPrompt, searchKeywords } = JSON.parse(analysisResponse.text);

    // 2. PRIORIDADE 1: GERAÇÃO POR IA (GEMINI IMAGE)
    try {
      const imageResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { 
          parts: [{ 
            text: `Cinematic art photography of ${visualPrompt}. Moody, high contrast, minimalist, architectural or natural elements. 9:16 portrait. ABSOLUTELY NO PEOPLE.` 
          }] 
        },
        config: { imageConfig: { aspectRatio: "9:16" } },
      }));

      const base64Data = imageResponse.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
      if (base64Data) return `data:image/jpeg;base64,${base64Data}`;
    } catch (genError) {
      console.warn("AI Generation unavailable, switching to Priority 2 (Pexels)...");
    }

    // 3. PRIORIDADE 2: BUSCA EM BANCO DE IMAGENS (PEXELS)
    const pexelsUrl = await fetchPexelsImage(searchKeywords);
    if (pexelsUrl) return pexelsUrl;

    // 4. PRIORIDADE 3: FALLBACK ESTÁTICO
    return getRandomFallbackImage();

  } catch (error) {
    console.error("Critical image system error:", error);
    return getRandomFallbackImage();
  }
}

import React, { useRef, useState, useEffect } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import { Spinner } from './Spinner';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  useEffect(() => {
    // Reseta o estado de carregamento se a URL mudar (regeneração)
    setIsImageLoaded(false);
  }, [quote.imageUrl]);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      scale: 2,
      backgroundColor: '#050608',
      logging: false,
      ignoreElements: (el) => el.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const link = document.createElement('a');
      link.download = `sophia-${quote.author.toLowerCase().replace(/\s+/g, '-')}.jpg`;
      link.href = canvas.toDataURL("image/jpeg", 0.9);
      link.click();
    } finally { setIsDownloading(false); }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating) return;
    setIsSharing(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: 'Pensamento Sophia', text: `"${quote.quote}" — ${quote.author}` });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Texto copiado para a área de transferência!');
      }
    } finally { setIsSharing(false); }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    try { await onRegenerateImage(quote); } finally { setIsRegenerating(false); }
  };

  return (
    <div className="space-y-4 sm:space-y-6 group animate-fadeIn w-full max-w-full">
      <div 
        ref={cardRef} 
