        {/* Loading Overlay */}
        {(isRegenerating || (!isImageLoaded && quote.imageUrl)) && (
            <div className="absolute inset-0 bg-[#050608] flex flex-col items-center justify-center z-50">
                <Spinner className="w-10 h-10 text-blue-500" />
