  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  useEffect(() => {
    setIsImageLoaded(false);
  }, [quote.imageUrl]);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      scale: 3, 
      backgroundColor: '#050608',
      logging: false,
      ignoreElements: (el) => el.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating || isDownloading) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const link = document.createElement('a');
      link.download = `sophia-${quote.author.toLowerCase().replace(/\s+/g, '-')}.jpg`;
      link.href = canvas.toDataURL("image/jpeg", 0.95);
      link.click();
    } finally { setIsDownloading(false); }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating || isSharing) return;
    setIsSharing(true);

    try {
      // Prioridade: Gerar uma nova imagem antes de compartilhar para garantir renovação
      if (onRegenerateImage) {
        setIsRegenerating(true);
        try {
          await onRegenerateImage(quote);
          // Pequena pausa para garantir que o DOM atualizou e a imagem começou a carregar
          await new Promise(resolve => setTimeout(resolve, 500));

          // Se a imagem ainda estiver carregando, esperamos um pouco mais (timeout de segurança)
          let waitTime = 0;
          const maxWait = 5000;
          while (!isImageLoaded && waitTime < maxWait) {
            await new Promise(resolve => setTimeout(resolve, 100));
            waitTime += 100;
          }
        } catch (err) {
          console.error("Erro ao regenerar imagem antes de compartilhar:", err);
        } finally {
          setIsRegenerating(false);
        }
      }

      const canvas = await captureImage();
      if (!canvas) return;

      const dataUrl = canvas.toDataURL("image/jpeg", 0.95);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-${Date.now()}.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ 
          files: [file], 
          title: 'Pensamento Sophia', 
          text: `"${quote.quote}" — ${quote.author}` 
        });
