        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Citação copiada! Você já pode colá-la onde quiser.');
      }
    } catch (err) {
      console.error("Erro no processo de compartilhamento:", err);
    } finally { 
      setIsSharing(false); 
    }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    try { await onRegenerateImage(quote); } finally { setIsRegenerating(false); }
  };

  return (
    <div className="space-y-6 group animate-fadeIn w-full">
