import React, { useRef, useState, useEffect } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import { Spinner } from './Spinner';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  useEffect(() => {
    setIsImageLoaded(false);
  }, [quote.imageUrl]);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      scale: 3, 
      backgroundColor: '#050608',
      logging: false,
      ignoreElements: (el) => el.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating || isDownloading) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const link = document.createElement('a');
      link.download = `sophia-${quote.author.toLowerCase().replace(/\s+/g, '-')}.jpg`;
      link.href = canvas.toDataURL("image/jpeg", 0.95);
      link.click();
    } finally { setIsDownloading(false); }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating || isSharing) return;
    setIsSharing(true);

    try {
      if (onRegenerateImage) {
        setIsRegenerating(true);
        try {
          await onRegenerateImage(quote);
          await new Promise(resolve => setTimeout(resolve, 500));

          let waitTime = 0;
          const maxWait = 5000;
          while (!isImageLoaded && waitTime < maxWait) {
            await new Promise(resolve => setTimeout(resolve, 100));
            waitTime += 100;
          }
        } catch (err) {
          console.error("Erro ao regenerar imagem antes de compartilhar:", err);
        } finally {
          setIsRegenerating(false);
        }
      }

      const canvas = await captureImage();
      if (!canvas) return;

      const dataUrl = canvas.toDataURL("image/jpeg", 0.95);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-${Date.now()}.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ 
          files: [file], 
          title: 'Pensamento Sophia', 
          text: `"${quote.quote}" — ${quote.author}` 
        });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Citação copiada! Você já pode colá-la onde quiser.');
      }
    } catch (err) {
      console.error("Erro no processo de compartilhamento:", err);
    } finally { 
      setIsSharing(false); 
    }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    try { await onRegenerateImage(quote); } finally { setIsRegenerating(false); }
  };

  const isBusy = isSharing || isDownloading || isRegenerating;

  return (
    <div className="space-y-6 group animate-fadeIn w-full">
      <div 
        ref={cardRef} 
        className="relative w-full aspect-[4/5] sm:aspect-[9/16] rounded-[2.5rem] sm:rounded-[4rem] overflow-hidden shadow-[0_30px_60px_-15px_rgba(0,0,0,0.7)] bg-[#0a0c10] border border-white/10 flex flex-col"
      >
        {/* Background Image with optimized fit */}
        {quote.imageUrl ? (
            <img 
                src={quote.imageUrl} 
                alt="Reflexão Visual" 
                onLoad={() => setIsImageLoaded(true)}
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-1000 scale-105 ${isImageLoaded ? 'opacity-100 blur-0 scale-100' : 'opacity-0 blur-xl'}`}
            />
        ) : <div className="absolute inset-0 bg-[#0a0c10]"></div>}

        {/* Cinematic Gradient Overlays */}
        <div className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-black/60 to-transparent z-10"></div>
        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-black/5 z-10"></div>
        <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/60 z-10"></div>

        {/* Content Container */}
        <div className="absolute inset-0 flex flex-col justify-center px-10 sm:px-16 text-center z-20 pointer-events-none">
            <div className="w-12 h-1 bg-gradient-to-r from-transparent via-blue-500/60 to-transparent mx-auto mb-10 rounded-full"></div>

            <div className="space-y-8">
              <blockquote className="font-serif-display text-3xl sm:text-5xl font-bold leading-[1.15] italic text-white text-shadow-sophia tracking-tight">
                  “{quote.quote}”
              </blockquote>

              <div className="flex items-center justify-center gap-4">
                <div className="h-px w-6 bg-white/20"></div>
                <cite className="font-serif-display text-xl sm:text-2xl text-blue-200/90 not-italic block tracking-wide font-medium text-shadow-author">
                    {quote.author}
                </cite>
                <div className="h-px w-6 bg-white/20"></div>
              </div>
            </div>
        </div>

        {/* Floating Action Buttons */}
        <div className="exclude-from-capture absolute top-8 right-8 flex flex-col gap-4 z-30">
            <button
                onClick={onImageChange}
                disabled={isBusy}
                className="p-4 rounded-full glass-action text-white/80 hover:text-white transition-all active:scale-90 shadow-xl disabled:opacity-40 disabled:cursor-not-allowed disabled:active:scale-100"
                title="Trocar imagem"
            >
                <RefreshIcon className={`w-5 h-5 ${isRegenerating ? 'animate-spin text-blue-400' : ''}`} />
            </button>
            <button
                onClick={() => onToggleFavorite?.(quote)}
                disabled={isBusy}
                className="p-4 rounded-full glass-action text-white/80 hover:text-white transition-all active:scale-90 shadow-xl disabled:opacity-40 disabled:cursor-not-allowed disabled:active:scale-100"
                title="Favoritar"
            >
                <HeartIcon className={`w-5 h-5 ${isFavorite ? 'text-red-500 fill-red-500' : ''}`} fill={isFavorite} />
            </button>
        </div>

        {/* Sophisticated Branding */}
        <div className="absolute bottom-12 left-0 right-0 flex justify-center items-center gap-3 opacity-60 z-20">
          <div className="h-px w-8 bg-white/30"></div>
          <span className="text-[10px] uppercase tracking-[0.8em] font-black text-white/80">SOPHIA</span>
          <div className="h-px w-8 bg-white/30"></div>
        </div>

        {/* Loading / Transition State Overlay */}
        {(isRegenerating || (!isImageLoaded && quote.imageUrl)) && (
            <div className="absolute inset-0 bg-[#050608] flex flex-col items-center justify-center z-50">
                <div className="relative">
                  <Spinner className="w-14 h-14 text-blue-500" />
                  <div className="absolute inset-0 blur-lg bg-blue-500/20 rounded-full animate-pulse"></div>
                </div>
                <p className="text-[11px] text-blue-400 mt-8 uppercase tracking-[0.6em] font-black animate-pulse">Tecendo Pensamento</p>
            </div>
        )}
      </div>

      {/* Main Action Buttons */}
      <div className="flex gap-4 px-2">
            <button
                onClick={handleShare}
                disabled={isBusy}
                className="flex-[2.5] bg-gradient-to-br from-blue-600 via-blue-600 to-blue-700 hover:from-blue-500 hover:to-blue-600 text-white font-black py-5 rounded-[2.5rem] flex items-center justify-center gap-3 transition-all active:scale-95 shadow-[0_15px_35px_-5px_rgba(37,99,235,0.4)] hover:shadow-[0_20px_45px_-5px_rgba(37,99,235,0.6)] text-[13px] uppercase tracking-widest disabled:opacity-30 disabled:cursor-not-allowed disabled:active:scale-100 disabled:shadow-none border border-blue-400/20"
            >
                {isSharing ? <Spinner className="w-5 h-5 text-white" /> : <ShareIcon className="w-5 h-5" />}
                {isSharing ? 'Criando Arte...' : 'Compartilhar Arte'}
            </button>
            <button
                onClick={handleDownload}
                disabled={isBusy}
                className="flex-1 bg-white/[0.03] hover:bg-white/[0.08] hover:border-blue-400/30 text-white py-5 rounded-[2.5rem] flex items-center justify-center transition-all active:scale-95 border border-white/10 shadow-lg disabled:opacity-20 disabled:cursor-not-allowed disabled:active:scale-100 disabled:hover:bg-white/[0.03] group/btn"
