import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import type { Quote } from '../types';

const FALLBACK_IMAGES = [
  "https://images.unsplash.com/photo-1507502707541-f369a3b18502?q=80&w=1080&auto=format&fit=crop", 
  "https://images.unsplash.com/photo-1516466723877-e4ec1d736c8a?q=80&w=1080&auto=format&fit=crop", 
  "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?q=80&w=1080&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?q=80&w=1080&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1501785888041-af3ef285b470?q=80&w=1080&auto=format&fit=crop"
];

const PHILOSOPHICAL_SCHOOLS = [
  "Estoicismo (Marco Aurélio, Sêneca)",
  "Existencialismo (Sartre, Camus)",
  "Budismo Zen e Filosofia Oriental",
  "Taoísmo (Lao Tzu)",
  "Filosofia Grega Clássica (Platão, Aristóteles)",
  "Iluminismo (Kant, Voltaire)",
  "Idealismo Alemão",
  "Fenomenologia e Hermenêutica",
  "Filosofia Contemporânea",
  "Pensadores Pré-Socráticos"
];

const getRandomFallbackImage = () => FALLBACK_IMAGES[Math.floor(Math.random() * FALLBACK_IMAGES.length)];
const generateId = () => Date.now().toString(36) + Math.random().toString(36).substring(2);

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function withRetry<T>(operation: () => Promise<T>, retries = 2, delay = 1500): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const errorMsg = error?.message?.toLowerCase() || "";
    if ((errorMsg.includes('overloaded') || errorMsg.includes('503') || errorMsg.includes('429')) && retries > 0) {
      await sleep(delay);
      return withRetry(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

export async function getTopicDescription(theme: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Descreva brevemente (máximo 120 caracteres) a essência filosófica de "${theme}". Seja poético e minimalista.`,
  }));
  return response.text || "";
}

export async function getPhilosophicalQuotes(theme: string): Promise<Quote[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-3-flash-preview", 
    contents: `Gere um array JSON com 3 citações curtas (máximo 15 palavras) e profundas em Português sobre o tema '${theme}'. Use filósofos ou pensadores reconhecidos.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            quote: { type: Type.STRING },
            author: { type: Type.STRING },
          },
          required: ["quote", "author"],
        }
      },
    },
  }));

  const jsonString = response.text.trim();
  const quotesRaw = JSON.parse(jsonString);
  return quotesRaw.map((q: any) => ({ ...q, id: generateId(), imageUrl: '' }));
}

export async function getRandomQuote(): Promise<Quote> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const randomSchool = PHILOSOPHICAL_SCHOOLS[Math.floor(Math.random() * PHILOSOPHICAL_SCHOOLS.length)];
  const entropy = Date.now();

  const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Gere uma citação filosófica INÉDITA e curta (máximo 15 palavras) em Português focada na escola: ${randomSchool}. 
    Certifique-se de que o autor seja real e reconhecido. 
    Contexto único de geração: ${entropy}.
    Retorne JSON.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          quote: { type: Type.STRING },
          author: { type: Type.STRING },
        },
        required: ["quote", "author"],
      },
    },
  }));

  const jsonString = response.text.trim();
  const dailyQuoteRaw = JSON.parse(jsonString);
  const imageUrl = await generateQuoteImage(dailyQuoteRaw.quote);
  return { ...dailyQuoteRaw, id: generateId(), imageUrl };
}

async function fetchPexelsImage(query: string): Promise<string | null> {
  const pexelsApiKey = process.env.PEXELS_API_KEY;
  if (!pexelsApiKey) return null;

  try {
    const safeQuery = `${query} landscape architecture minimalist -person -people`;
    const response = await fetch(`https://api.pexels.com/v1/search?query=${encodeURIComponent(safeQuery)}&per_page=1&orientation=portrait`, {
      headers: { Authorization: pexelsApiKey }
    });
    const data = await response.json();
    return data.photos?.[0]?.src?.large2x || null;
  } catch (error) {
    console.error("Pexels error:", error);
    return null;
  }
}

export async function generateQuoteImage(quoteText: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const analysisResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analise o sentimento desta frase: "${quoteText}".
      Retorne um JSON com:
      1. visualPrompt: A poetic description for image generation (English). Focus on textures, landscapes, objects or abstract light.
      2. searchKeywords: 3 English keywords for high-end photography search.
      IMPORTANT: STRICTLY NO HUMANS, NO FACES, NO BODY PARTS.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualPrompt: { type: Type.STRING },
            searchKeywords: { type: Type.STRING },
          },
          required: ["visualPrompt", "searchKeywords"]
        }
      }
    }));

    const { visualPrompt, searchKeywords } = JSON.parse(analysisResponse.text);

    try {
      const imageResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { 
          parts: [{ 
            text: `Cinematic art photography of ${visualPrompt}. Moody, high contrast, minimalist, architectural or natural elements. 9:16 portrait. ABSOLUTELY NO PEOPLE.` 
          }] 
        },
        config: { imageConfig: { aspectRatio: "9:16" } },
      }));

      const base64Data = imageResponse.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
      if (base64Data) return `data:image/jpeg;base64,${base64Data}`;
    } catch (genError) {
      console.warn("AI Generation unavailable, switching to Priority 2 (Pexels)...");
    }

    const pexelsUrl = await fetchPexelsImage(searchKeywords);
    if (pexelsUrl) return pexelsUrl;

    return getRandomFallbackImage();

  } catch (error) {
    console.error("Critical image system error:", error);
    return getRandomFallbackImage();
  }
}

import React, { useState, useCallback, useEffect } from 'react';
import { SearchBar } from './components/SearchBar';
import { QuoteCard } from './components/QuoteCard';
import { Spinner } from './components/Spinner';
import { getPhilosophicalQuotes, getRandomQuote, generateQuoteImage, getTopicDescription } from './services/geminiService';
import type { Quote } from './types';
import { SophiaIcon, SearchIcon, BookmarkIcon, RefreshIcon, DownloadIcon } from './components/Icons';

type ViewState = 'search' | 'favorites';

const App: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [topicDescription, setTopicDescription] = useState<string>('');
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [randomQuote, setRandomQuote] = useState<Quote | null>(null);
  const [isRandomLoading, setIsRandomLoading] = useState<boolean>(true);

  const [favorites, setFavorites] = useState<Quote[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('search');

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallBtn, setShowInstallBtn] = useState(false);

  const fetchRandomQuote = useCallback(async () => {
    setIsRandomLoading(true);
    setError(null);
    try {
      const quote = await getRandomQuote();
      setRandomQuote(quote);
    } catch (err: any) {
      console.error("Erro ao buscar citação aleatória:", err);
    } finally {
      setIsRandomLoading(false);
    }
  }, []);

  const resetToHome = useCallback(() => {
    setSearchTerm('');
    setQuotes([]);
    setTopicDescription('');
    setCurrentView('search');
    // Força uma nova sugestão ao "entrar" novamente na home
    fetchRandomQuote();
  }, [fetchRandomQuote]);

  useEffect(() => {
    const savedFavorites = localStorage.getItem('sophia_favorites');
    if (savedFavorites) {
      try {
        setFavorites(JSON.parse(savedFavorites));
      } catch (e) { console.error(e); }
    }

    fetchRandomQuote();

    const handleBeforeInstall = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setShowInstallBtn(true);
    };

    const handleAppInstalled = () => {
      setShowInstallBtn(false);
      setDeferredPrompt(null);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstall);
    window.addEventListener('appinstalled', handleAppInstalled);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstall);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, [fetchRandomQuote]);

  useEffect(() => {
    localStorage.setItem('sophia_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setShowInstallBtn(false);
    }
    setDeferredPrompt(null);
  };

  const handleSearch = useCallback(async () => {
    if (!searchTerm.trim()) {
      resetToHome();
      return;
