import React, { useState, useCallback, useEffect } from 'react';
import { SearchBar } from './components/SearchBar.tsx';
import { QuoteCard } from './components/QuoteCard.tsx';
import { Spinner } from './components/Spinner.tsx';
import { getPhilosophicalQuotes, getRandomQuote, generateQuoteImage, getTopicDescription } from './services/geminiService.ts';
import type { Quote } from './types.ts';
import { SophiaIcon, SearchIcon, BookmarkIcon, RefreshIcon, DownloadIcon } from './components/Icons.tsx';

type ViewState = 'search' | 'favorites';

const App: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [topicDescription, setTopicDescription] = useState<string>('');
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [randomQuote, setRandomQuote] = useState<Quote | null>(null);
  const [isRandomLoading, setIsRandomLoading] = useState<boolean>(true);

  const [favorites, setFavorites] = useState<Quote[]>([]);
  const [currentView, setCurrentView] = useState<ViewState>('search');

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallBtn, setShowInstallBtn] = useState(false);

  const fetchRandomQuote = useCallback(async () => {
    setIsRandomLoading(true);
    setError(null);
    try {
      const quote = await getRandomQuote();
      setRandomQuote(quote);
    } catch (err: any) {
      setError("Não foi possível carregar a sugestão do dia.");
    } finally {
      setIsRandomLoading(false);
    }
  }, []);

  const resetToHome = useCallback(() => {
    setSearchTerm('');
    setQuotes([]);
    setTopicDescription('');
    setCurrentView('search');
    fetchRandomQuote();
  }, [fetchRandomQuote]);

  useEffect(() => {
    const savedFavorites = localStorage.getItem('sophia_favorites');
    if (savedFavorites) {
      try { setFavorites(JSON.parse(savedFavorites)); } catch (e) { console.error(e); }
    }
    fetchRandomQuote();

    const handleBeforeInstall = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setShowInstallBtn(true);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstall);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstall);
  }, [fetchRandomQuote]);

  useEffect(() => {
    localStorage.setItem('sophia_favorites', JSON.stringify(favorites));
  }, [favorites]);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') setShowInstallBtn(false);
    setDeferredPrompt(null);
  };

  const handleSearch = useCallback(async () => {
    if (!searchTerm.trim()) {
      resetToHome();
      return;
    }
    setIsLoading(true);
    setError(null);
    setQuotes([]);
    setTopicDescription('');
    setCurrentView('search');

    try {
      const [description, fetchedQuotes] = await Promise.all([
        getTopicDescription(searchTerm),
        getPhilosophicalQuotes(searchTerm)
      ]);
      setTopicDescription(description);

      if (fetchedQuotes.length === 0) {
        setError('Nenhum pensamento encontrado.');
        return;
      }

      const resolvedQuotes = await Promise.all(fetchedQuotes.map(async (quote) => {
        const imageUrl = await generateQuoteImage(quote.quote);
        return { ...quote, imageUrl };
      }));
      setQuotes(resolvedQuotes);
    } catch (err: any) {
      setError("Ocorreu um erro ao buscar sabedoria.");
    } finally {
      setIsLoading(false);
    }
  }, [searchTerm, resetToHome]);

  const handleRegenerateImage = async (quote: Quote) => {
    try {
      const newImageUrl = await generateQuoteImage(quote.quote);
      setQuotes(prev => prev.map(q => q.id === quote.id ? { ...q, imageUrl: newImageUrl } : q));
      if (randomQuote?.id === quote.id) setRandomQuote(prev => prev ? { ...prev, imageUrl: newImageUrl } : null);
      setFavorites(prev => prev.map(q => q.quote === quote.quote ? { ...q, imageUrl: newImageUrl } : q));
    } catch (err) { console.error(err); }
  };

  const toggleFavorite = (quote: Quote) => {
    setFavorites(prev => {
      const exists = prev.some(fav => fav.quote === quote.quote);
      return exists ? prev.filter(fav => fav.quote !== quote.quote) : [quote, ...prev];
    });
  };

  return (
    <div className="bg-[#020305] min-h-screen text-white flex justify-center selection:bg-blue-500/30">
      <div className="w-full max-w-lg min-h-screen flex flex-col relative overflow-x-hidden">

        {/* Superior Header - Sophisticated & Minimal */}
        <header className="sticky top-0 z-50 px-8 pt-8 pb-4 bg-[#020305]/60 backdrop-blur-2xl">
          <div className="flex items-center justify-between mb-8">
            <button onClick={resetToHome} className="flex items-center gap-3 active:scale-95 transition-transform">
              <div className="p-2 bg-blue-600/10 rounded-xl border border-blue-600/20">
                <SophiaIcon className="w-6 h-6 text-blue-500" />
              </div>
              <h1 className="text-xl font-black tracking-[0.3em] text-white/90">SOPHIA</h1>
            </button>

            {showInstallBtn && (
              <button 
                onClick={handleInstallClick}
                className="p-3 bg-blue-600/10 border border-blue-600/20 rounded-full text-blue-500 active:scale-90 transition-all"
              >
                <DownloadIcon className="w-4 h-4" />
              </button>
            )}
          </div>

          <nav className="flex bg-white/5 p-1 rounded-2xl border border-white/5">
             <button 
                onClick={() => setCurrentView('search')}
                className={`flex-1 flex items-center justify-center gap-2 py-3.5 rounded-xl text-[11px] uppercase tracking-widest font-bold transition-all duration-500 ${currentView === 'search' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-gray-500'}`}
             >
                <SearchIcon className="w-3.5 h-3.5" /> Explorar
             </button>
             <button 
                onClick={() => setCurrentView('favorites')}
                className={`flex-1 flex items-center justify-center gap-2 py-3.5 rounded-xl text-[11px] uppercase tracking-widest font-bold transition-all duration-500 ${currentView === 'favorites' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-gray-500'}`}
             >
                <BookmarkIcon className="w-3.5 h-3.5" fill={currentView === 'favorites'} /> Coleção
             </button>
          </nav>
        </header>

        <main className="flex-1 px-8 pb-12 space-y-12 overflow-y-auto scrollbar-hide">
          {currentView === 'favorites' ? (
            <div className="animate-reveal space-y-10 pt-4">
                {favorites.length === 0 ? (
                    <div className="flex flex-col justify-center items-center py-40 text-center opacity-20">
                        <BookmarkIcon className="w-16 h-16 mb-6" />
                        <p className="text-[10px] uppercase tracking-[0.4em] font-black italic">Sua curadoria está vazia.</p>
                    </div>
                ) : (
                    <>
                        <h2 className="text-center font-serif-display text-2xl text-white/40 italic">O Teu Acervo de Sabedoria</h2>
                        {favorites.map((fav) => (
                            <QuoteCard key={fav.id} quote={fav} isFavorite={true} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </>
                )}
            </div>
          ) : (
            <div className="animate-reveal space-y-10 pt-4">
                <SearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} onSearch={handleSearch} isLoading={isLoading} />

                {isLoading ? (
                    <div className="flex flex-col justify-center items-center py-32">
                      <div className="relative">
                        <Spinner className="w-10 h-10 text-blue-500" />
                        <div className="absolute inset-0 blur-xl bg-blue-500/20 rounded-full animate-pulse"></div>
                      </div>
                      <p className="mt-10 text-blue-500/60 text-[10px] uppercase tracking-[0.5em] font-black animate-pulse text-center">Invocando o Oráculo...</p>
                    </div>
                ) : error ? (
                    <div className="py-20 text-center px-6">
                        <p className="text-xs uppercase tracking-widest font-bold text-red-400/50 italic">{error}</p>
                        <button onClick={resetToHome} className="mt-8 text-blue-500 text-[10px] font-black uppercase tracking-[0.3em]">Tentar novamente</button>
                    </div>
                ) : quotes.length > 0 ? (
                    <div className="space-y-16">
                        {topicDescription && (
                          <div className="px-6 py-8 border-l border-white/10 bg-white/2 rounded-r-3xl animate-reveal">
                            <p className="font-serif-display text-lg text-gray-400 italic leading-relaxed">
                              {topicDescription}
                            </p>
                          </div>
                        )}
                        {quotes.map((quote, index) => (
                            <QuoteCard key={quote.id || index} quote={quote} isFavorite={favorites.some(f => f.quote === quote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                        ))}
                    </div>
                ) : (
                    <div className="space-y-12">
                        {isRandomLoading ? (
                            <div className="flex flex-col justify-center items-center py-24">
                                <Spinner className="w-8 h-8 text-gray-700" />
                            </div>
                        ) : randomQuote && (
                            <div className="animate-reveal flex flex-col">
                                <div className="flex items-center justify-between mb-8 px-2">
                                  <h2 className="font-serif-display text-2xl text-white/30 italic">Luz para o dia</h2>
                                  <button onClick={fetchRandomQuote} className="p-3 rounded-full bg-white/5 hover:bg-white/10 text-blue-500 transition-all border border-white/5 active:rotate-90">
                                    <RefreshIcon className="w-4 h-4" />
                                  </button>
                                </div>
                                <QuoteCard quote={randomQuote} isFavorite={favorites.some(f => f.quote === randomQuote.quote)} onToggleFavorite={toggleFavorite} onRegenerateImage={handleRegenerateImage} />
                            </div>
                        )}
                    </div>
                )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { SearchIcon } from './Icons';

interface SearchBarProps {
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onSearch: () => void;
  isLoading: boolean;
}

export const SearchBar: React.FC<SearchBarProps> = ({ searchTerm, setSearchTerm, onSearch, isLoading }) => {
  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') onSearch();
  };

  return (
    <div className="relative group animate-reveal">
      <div className="absolute inset-y-0 left-6 flex items-center pointer-events-none">
        <SearchIcon className="w-4 h-4 text-gray-600 group-focus-within:text-blue-500 transition-colors" />
      </div>
      <input
        type="text"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder="O que deseja refletir hoje?..."
        disabled={isLoading}
        className="w-full bg-white/[0.03] border border-white/5 rounded-[1.8rem] py-5 pl-14 pr-6 text-[13px] text-white placeholder-gray-600 focus:outline-none focus:ring-1 focus:ring-white/10 focus:bg-white/[0.05] transition-all duration-500"
      />
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import { Spinner } from './Spinner';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  useEffect(() => {
    setIsImageLoaded(false);
  }, [quote.imageUrl]);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      scale: 3, 
      backgroundColor: '#020305',
      logging: false,
      ignoreElements: (el) => el.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || isRegenerating || isDownloading) return;
    setIsDownloading(true);
    try {
      const canvas = await captureImage();
      if (!canvas) return;
      const link = document.createElement('a');
      link.download = `sophia-${Date.now()}.jpg`;
      link.href = canvas.toDataURL("image/jpeg", 0.95);
      link.click();
    } finally { setIsDownloading(false); }
  };

  const handleShare = async () => {
    if (!cardRef.current || isRegenerating || isSharing) return;
    setIsSharing(true);

    try {
      const canvas = await captureImage();
      if (!canvas) return;

      const dataUrl = canvas.toDataURL("image/jpeg", 0.95);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-${Date.now()}.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ 
          files: [file], 
          title: 'Pensamento Sophia', 
          text: `"${quote.quote}" — ${quote.author}` 
        });
      } else {
        await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}`);
        alert('Texto copiado com sucesso!');
      }
    } catch (err) {
      console.error("Erro no compartilhamento:", err);
    } finally { 
      setIsSharing(false); 
    }
  };

  const onImageChange = async () => {
    if (!onRegenerateImage || isRegenerating) return;
    setIsRegenerating(true);
    try { await onRegenerateImage(quote); } finally { setIsRegenerating(false); }
  };

  const isBusy = isSharing || isDownloading || isRegenerating;

  return (
    <div className="space-y-6 animate-reveal w-full">
      <div 
        ref={cardRef} 
        className="relative w-full aspect-[4/5] sm:aspect-[9/16] rounded-[2.5rem] overflow-hidden shadow-2xl bg-[#0a0c10] border border-white/5 flex flex-col group"
      >
        {/* Visual Engine */}
        {quote.imageUrl ? (
            <img 
                src={quote.imageUrl} 
                alt="Pensamento" 
                onLoad={() => setIsImageLoaded(true)}
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-1000 ${isImageLoaded ? 'opacity-100 scale-100' : 'opacity-0 scale-110 blur-2xl'}`}
            />
        ) : <div className="absolute inset-0 bg-[#0a0c10]"></div>}

        {/* Cinematic Overlays */}
        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/30 to-black/10 z-10"></div>
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.4)_100%)] z-10"></div>

        {/* Aesthetic Quote Content */}
        <div className="absolute inset-0 flex flex-col justify-center px-8 sm:px-14 text-center z-20 pointer-events-none">
            <div className="space-y-10">
              <blockquote className="font-serif-display text-3xl sm:text-4xl leading-tight italic text-white text-shadow-sophia tracking-wide font-light">
                  “{quote.quote}”
              </blockquote>

              <div className="inline-flex items-center gap-3 px-6 py-2.5 rounded-full bg-black/30 backdrop-blur-md border border-white/10 mx-auto">
                <cite className="font-serif-display text-lg text-blue-200/80 not-italic tracking-widest font-medium">
                    {quote.author}
                </cite>
              </div>
            </div>
        </div>

        {/* Internal Action Panel */}
        <div className="exclude-from-capture absolute top-6 right-6 flex flex-col gap-3 z-30">
            <button
                onClick={onImageChange}
                disabled={isBusy}
                className="p-3.5 rounded-full glass-action text-white/60 hover:text-white transition-all active:scale-90 shadow-xl disabled:opacity-20"
                title="Novo cenário"
            >
                <RefreshIcon className={`w-4 h-4 ${isRegenerating ? 'animate-spin text-blue-500' : ''}`} />
            </button>
            <button
                onClick={() => onToggleFavorite?.(quote)}
                disabled={isBusy}
                className="p-3.5 rounded-full glass-action text-white/60 hover:text-white transition-all active:scale-90 shadow-xl"
                title="Favoritar"
            >
                <HeartIcon className={`w-4 h-4 ${isFavorite ? 'text-red-500 fill-red-500' : ''}`} fill={isFavorite} />
            </button>
        </div>

        {/* Minimal Signature */}
        <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-3 opacity-30 z-20">
          <span className="text-[9px] uppercase tracking-[0.6em] font-black text-white">SOPHIA</span>
        </div>

        {/* Elegant Loading Stage */}
        {(isRegenerating || (!isImageLoaded && quote.imageUrl)) && (
            <div className="absolute inset-0 bg-[#020305]/95 backdrop-blur-3xl flex flex-col items-center justify-center z-50 transition-opacity">
                <Spinner className="w-10 h-10 text-blue-600" />
                <p className="text-[9px] text-blue-600 mt-6 uppercase tracking-[0.4em] font-black animate-pulse">Tecendo Arte</p>
            </div>
        )}
      </div>

      {/* Hero Interaction Bar */}
      <div className="flex gap-3 px-1">
            <button
                onClick={handleShare}
                disabled={isBusy}
                className="btn-glow flex-[3] bg-blue-600 hover:bg-blue-500 text-white font-black py-5 rounded-[1.8rem] flex items-center justify-center gap-3 transition-all text-[12px] uppercase tracking-[0.15em] disabled:opacity-30 border border-blue-400/20"
            >
                {isSharing ? <Spinner className="w-4 h-4 text-white" /> : <ShareIcon className="w-4 h-4" />}
                {isSharing ? 'Preparando...' : 'Compartilhar'}
            </button>
            <button
                onClick={handleDownload}
                disabled={isBusy}
                className="flex-1 bg-white/5 hover:bg-white/10 text-white py-5 rounded-[1.8rem] flex items-center justify-center transition-all border border-white/5 disabled:opacity-20 group"
                title="Salvar"
            >
                {isDownloading ? <Spinner className="w-4 h-4 text-blue-500" /> : <DownloadIcon className="w-5 h-5 group-hover:text-blue-500 transition-colors" />}
            </button>
      </div>
    </div>
  );
};

